const ROOM_DEFS = [
{id:0,name:"Lava Bridge",desc:"You stand before the Lava Bridge, the only way to the Castle of Dread.",exits:{north:1,south:-1},type:"start"},
{id:1,name:"Shadow Hall",desc:"Cold air spills from the corridor ahead. <span style='color:#8f8fb8'>Shadows cling to the stone</span> a heartbeat longer than they should, and somewhere beyond the walls something scratches once... then stops.",exits:{east:2,north:10},type:"normal"},
{id:2,name:"Old Armory",desc:"Rusted blades lie in heaps beneath sagging weapon racks. A split helmet still bears <span style='color:#9d4d4d'>three dark stains</span>, while a shield on the far wall slowly rocks although there is no wind.",exits:{west:1,east:3},type:"normal"},
{id:3,name:"Ash Chamber",desc:"Grey ash blankets the floor like winter snow. Each step sends pale curls into the air, revealing <span style='color:#d7b56d'>brief glowing embers</span> underneath. Something large has crossed this room recently.",exits:{west:2,north:13},type:"normal"},
{id:4,name:"Collapsed Hall",desc:"Half the ceiling has surrendered to time. Broken pillars form a crooked tunnel through the rubble, and from somewhere beneath the stones comes a faint, patient tapping.",exits:{east:5,south:14},type:"normal"},
{id:5,name:"Ancient Library",desc:"Shelves climb higher than your torchlight can reach. Most books have rotted into black pulp, yet one row remains perfectly clean. Their titles seem to change whenever you look away.",exits:{west:4,east:6},type:"normal"},
{id:6,name:"Broken Gallery",desc:"Portraits have been slashed from their frames, leaving only fragments of painted eyes and hands. A cracked marble statue points toward an empty wall as if warning you not to stand there.",exits:{west:5,north:16},type:"normal"},
{id:7,name:"Dusty Kitchen",desc:"Copper pots hang above a cold hearth. The tables are set for a feast that never happened, complete with petrified bread and a carving knife buried deep in the wood.",exits:{east:8,south:17},type:"normal"},
{id:8,name:"Butler's Room",desc:"A row of immaculate coats hangs beside bottles of bitter perfume. On the desk rests a portrait whose eyes have been carefully cut out. Behind it someone has written: HE STILL LISTENS.",exits:{west:7,east:9},type:"normal"},
{id:9,name:"Wine Cellar",desc:"Broken bottles glitter underfoot and the air is sweet with spoiled wine. One barrel is still sealed. From inside it comes a single hollow knock whenever you turn your back.",exits:{west:8,north:19},type:"normal"},
{id:10,name:"Hall of Chains",desc:"Chains descend from the ceiling in uneven rows. They sway without wind, brushing together with a thin metallic whisper. Several end in empty iron collars.",exits:{south:1,north:20},type:"normal"},
{id:11,name:"Stone Corridor",desc:"Moss grows thick between the stones and icy water runs in narrow channels beneath your boots. Far ahead, footsteps echo in perfect rhythm with yours—until you stop.",exits:{east:12,south:21},type:"normal"},
{id:12,name:"Scribe's Den",desc:"Torn scrolls carpet the floor around a desk split cleanly in two. Every inkwell is dry except one, where purple ink slowly circles itself like something alive.",exits:{west:11,east:13},type:"normal"},
{id:13,name:"Upper Ash Chamber",desc:"Ash reaches your ankles here. Thin trails move beneath the surface as if small creatures are burrowing through it, but whenever you disturb the ash you find nothing.",exits:{west:12,south:3,east:14},type:"normal"},
{id:14,name:"Haunted Gallery",desc:"The portraits are intact here—and every painted face is turned toward you. When you move, a woman in a blue dress appears one frame closer than before.",exits:{west:13,north:4,east:15},type:"normal"},
{id:15,name:"Iron Armory",desc:"Rows of black armor stand at attention. Most are headless. One suit still wears a helmet, its visor lowered, and a thin line of fresh dust marks where it recently shifted its weight.",exits:{west:14,north:16},type:"normal"},
{id:16,name:"Balcony",desc:"Hot wind pours through a shattered window and carries the smell of sulfur. Far below, lava paints the cliffside orange. For a moment you see a vast shape move through the smoke outside.",exits:{south:6,east:17},type:"normal"},
{id:17,name:"Courtyard",desc:"Dead grass surrounds a dry fountain filled with black feathers. Two gargoyles crouch above the doors. One has rainwater in its mouth. The other has blood.",exits:{north:7,west:16,south:27},type:"normal"},
{id:18,name:"Abandoned Well",desc:"The old well disappears into darkness. A damp rope once hung here, but only a frayed knot remains. Something splashes far below, followed by a sound uncomfortably close to laughter.",exits:{east:19,north:28},type:"normal"},
{id:19,name:"Gardener's Shed",desc:"Rusty tools lie beneath vines that have forced their way through the walls. Pale mushrooms grow from a pair of abandoned boots. The laces are still tied.",exits:{west:18,south:9,north:29},type:"normal"},
{id:20,name:"Ritual Chamber",desc:"Blackened candles form a broken circle around chalk symbols scraped into the floor. At its center sits a small wooden chair facing the wrong direction.",exits:{south:10,east:21},type:"normal"},
{id:21,name:"Damp Cell",desc:"Water seeps through the walls and gathers around an iron door crusted with rust. Deep scratches cover the inside of the cell, all of them ending at shoulder height.",exits:{west:20,north:11,east:22},type:"normal"},
{id:22,name:"Storage Room",desc:"Crates and barrels crowd the room in unstable towers. Several have been opened from the inside. A trail of tiny footprints vanishes beneath the largest stack.",exits:{west:21,south:23},type:"normal"},
{id:23,name:"Smith's Workshop",desc:"A cold forge dominates the chamber. Hammers still hang in careful order, and the anvil bears a deep groove shaped like a blade that was struck far too hard.",exits:{north:22,east:24},type:"normal"},
{id:24,name:"Sewer Entry",desc:"A low archway descends beneath the castle. Green water glimmers between the stones, and something has carved arrows into the wall—some pointing forward, some pointing back.",exits:{west:23,south:25},type:"normal"},
{id:25,name:"Sewer Tunnel",desc:"The tunnel narrows around you. Water ripples ahead although nothing moves through it. A half-submerged child's shoe turns slowly in the current.",exits:{north:24,east:26},type:"normal"},
{id:26,name:"Hidden Cellar",desc:"Shelves hold jars of teeth, insects and things without names. One jar is empty except for a label reading DO NOT LET IT OUT.",exits:{west:25,north:27},type:"normal"},
{id:27,name:"Collapsed Courtyard",desc:"A fallen statue blocks half the yard, its stone face shattered against the ground. Beneath the broken torso, a narrow gap breathes warm air like a sleeping animal.",exits:{north:17,south:37,east:28},type:"normal"},
{id:28,name:"Greenhouse",desc:"Most plants are dead, but one white flower blooms beneath cracked glass. Its petals turn toward you as you cross the room. The vines around its pot do not.",exits:{west:27,south:18,east:29},type:"normal"},
{id:29,name:"Upper Balcony",desc:"From here the main hall lies far below. Shapes move through the darkness beneath you, stopping whenever you lean over the railing to look.",exits:{west:28,south:19,north:39},type:"normal"},
{id:30,name:"Servant's Passage",desc:"The corridor is barely shoulder-wide. Names have been carved into the wood at regular intervals. The last one is fresh.",exits:{east:31,north:40},type:"normal"},
{id:31,name:"Abandoned Nursery",desc:"Faded toys sit in a perfect circle around a rocking horse. The horse moves gently by itself. Every doll has been turned to face the door.",exits:{west:30,east:32},type:"normal"},
{id:32,name:"Sickroom",desc:"Iron beds line the walls beneath yellowed sheets. The air still smells faintly of medicine. One pillow is indented as if someone has only just risen from it.",exits:{west:31,south:33},type:"normal"},
{id:33,name:"Secret Alcove",desc:"A hidden bookcase has swung aside to reveal a cramped chamber. Strange maps cover the walls, each showing a different version of the castle—and none matching the route you took.",exits:{north:32,east:34},type:"normal"},
{id:34,name:"Upper Crypt",desc:"Cracked sarcophagi line the chamber. Frost coats the stone despite the heat outside. One lid has been pushed aside from within, leaving a handprint in the ice.",exits:{west:33,east:35,south:44},type:"normal"},
{id:35,name:"Torture Room",desc:"The machines have rusted, but the leather straps remain strangely supple. A bell hangs beside the rack with a note beneath it: RING WHEN FINISHED.",exits:{west:34,north:36},type:"normal"},
{id:36,name:"Winding Stairs",desc:"The spiral staircase climbs through a shaft of black stone. The steps are worn smooth in the center, as if generations of feet walked upward—but never back down.",exits:{south:35,north:46},type:"normal"},
{id:37,name:"Flooded Passage",desc:"Black water reaches your ankles. Pale shapes dart away from your boots, too large to be fish. Every few seconds the water rises as if the tunnel itself is breathing.",exits:{north:27,east:38},type:"normal"},
{id:38,name:"Mosaic Hall",desc:"Broken tiles depict a crowned figure standing above a kneeling dragon. Someone has smashed only the face of the crowned figure, leaving the dragon untouched.",exits:{west:37,north:39},type:"normal"},
{id:39,name:"Upper Garden",desc:"Night-blooming flowers cast a faint violet glow. Their fragrance is beautiful at first—until you notice the plants are rooted in old helmets instead of soil.",exits:{south:29,west:38,east:40},type:"normal"},
{id:40,name:"Hall of Mirrors",desc:"A hundred warped reflections surround you. Most copy your movements. One does not. In the farthest mirror, your reflection stands with its back turned.",exits:{west:39,south:30,north:41},type:"normal"},
{id:41,name:"Cursed Gallery",desc:"Paintings weep thin crimson lines onto the floor. Behind one ornate silver frame, you hear the soft click of a hidden mechanism.",exits:{south:40,east:42},type:"normal"},
{id:42,name:"Locked Study",desc:"A massive desk faces a wall of arcane symbols. The runes pulse faintly when you approach, as though waiting for something ancient to answer them.",exits:{west:41,south:43},type:"normal"},
{id:43,name:"Obsidian Vault",desc:"The walls are seamless black glass. Your footsteps return a second too late, and a circular rune in the floor hums beneath your weight.",exits:{north:42,east:44},type:"normal"},
{id:44,name:"Catacomb Entrance",desc:"Bones lie in careful rows beside the stairs, each skull facing downward. A cold draft rises from below carrying the smell of wet stone and extinguished candles.",exits:{west:43,north:34,south:45},type:"normal"},
{id:45,name:"Deep Catacombs",desc:"Darkness swallows the passage almost completely. The walls are covered in handprints made from soot, all pointing toward the same sealed niche.",exits:{north:44,east:46},type:"normal"},
{id:46,name:"Tower Stairs",desc:"The tower staircase climbs steeply around a hollow shaft. Higher up, several steps are missing entirely, leaving only cracked stone and open darkness.",exits:{west:45,south:36,north:47},type:"normal"},
{id:47,name:"Watchtower",desc:"Mist coils around the shattered windows. From here the castle looks impossibly large, as if entire wings exist outside the walls you explored.",exits:{south:46,east:48},type:"normal"},
{id:48,name:"Ancient Bell Room",desc:"A colossal bronze bell hangs above a broken stairwell. The final flight has collapsed into the tower shaft. A rusted iron ring in the wall looks strong enough to anchor a Rope.",exits:{west:47,north:49},type:"normal"},
{id:49,name:"Tower Apex",desc:"The tower roof groans beneath a sky full of ash. A vast sealed door stands ahead, its surface carved with four empty key-shaped wounds. Behind it, something waits.",exits:{south:48},type:"boss"}
];

