function computeRoomDepths(){const dist=new Array(gameState.dungeon.length).fill(null);dist[0]=0;const q=[0];while(q.length){const id=q.shift();const r=gameState.dungeon[id];for(const dir in r.exits){const dest=r.exits[dir];if(typeof dest==="number"&&dest>=0&&dist[dest]===null){dist[dest]=dist[id]+1;q.push(dest);}}}return dist;}

// MAP LAYOUT: a régi térkép id==row*10+col-ot feltételezett, de a valódi exit-gráf nem szigorú rács
// (pl. az 1-es szoba "north"-ja és a 10-es szoba "north"-ja nem ugyanazt az offsetet használja),
// ezért a régi térkép nem egyezett a tényleges mozgással. Most a start szobától a valódi exit-gráfon
// bejárva (BFS) rendelünk (x,y) koordinátát minden szobához az north/south/east/west irányok mentén,
// így a térkép a "go [irány]" parancsokkal összhangban lesz a legtöbb szobánál.
// FONTOS: az 50 szobás gráf nem ültethető be TÖKÉLETESEN egy sík rácsba (van pár "hurok", ahol egy
// másik útvonalon visszaérve más koordináta jönne ki) — ez nem hiba, hanem a kastély szerkezetéből
// adódik. Ezért a térkép "megközelítő", nem szó szerinti geometria; lásd MAP_HAS_LOOPS jelzést lent.
const DIRECTION_DELTAS={north:{dx:0,dy:-1},south:{dx:0,dy:1},east:{dx:1,dy:0},west:{dx:-1,dy:0}};
function computeRoomCoords(){const coords={0:{x:0,y:0}};const visited=new Set([0]);const q=[0];while(q.length){const id=q.shift();const r=gameState.dungeon[id];if(!r)continue;const c=coords[id];for(const dir in r.exits){const dest=r.exits[dir];if(typeof dest!=="number"||dest<0)continue;const delta=DIRECTION_DELTAS[dir];if(!delta)continue;if(!visited.has(dest)){visited.add(dest);coords[dest]={x:c.x+delta.dx,y:c.y+delta.dy};q.push(dest);}}}return coords;}

// SZOBA-POOL / TIER RENDSZER
// A kastély 5 fix "szakaszra" (tier) van osztva a starttól mért TÉNYLEGES lépéstávolság (BFS depth) alapján.
// A szakaszhatárok statikusak (mindig ugyanott vannak), de az, hogy melyik konkrét enemy jön elő egy adott
// szakaszon belül, továbbra is véletlenszerű a szakasz saját pool-jából. Ez a "váz statikus, tartalom random" elv.
//   Tier 1 – Game Start (kb. 8 szoba, depth 0-4): a leggyengébb lények
//   Tier 2 – Castle Basement (kb. 16 szoba, depth 5-9)
//   Tier 3 – Courtyard & Garden (kb. 10 szoba, depth 10-13)
//   Tier 4 – Upper Manor (kb. 8 szoba, depth 14-17)
//   Tier 5 – Tower Approach (kb. 8 szoba, depth 18+): a legerősebb lények, közvetlenül a Boss előtt
const ZONE_DEFS=[
 {name:"Game Start",min:0,max:4,pool:["Skeleton","Zombie","Ghoul","Giant Spider","Feral Hound","Wailing Child"]},
 {name:"Castle Basement",min:5,max:9,pool:["Wraith","Banshee","Vampire","Shadow","Mummy","Possessed Armor","Bog Wretch"]},
 {name:"Courtyard & Garden",min:10,max:13,pool:["Gargoyle","Ogre","Ghoul","Giant Spider","Shadow","Feral Hound"]},
 {name:"Upper Manor",min:14,max:17,pool:["Dark Mage","Undead Knight","Vampire","Mummy","Possessed Armor","Withered Priest","Crypt Warden"]},
 {name:"Tower Approach",min:18,max:99,pool:["Undead Knight","Dark Mage","Gargoyle","Ogre","Stone Sentinel","Crypt Warden"]}
];
function getZonePool(id){const depth=(gameState.roomDepth&&gameState.roomDepth[id]!=null)?gameState.roomDepth[id]:id;const z=ZONE_DEFS.find(zz=>depth>=zz.min&&depth<=zz.max);if(!z)return ENEMY_POOL;const filtered=ENEMY_POOL.filter(e=>z.pool.includes(e.name));return filtered.length?filtered:ENEMY_POOL;}

// --- APPROACHING THREAT / ECHO HINTS ---
// Sejtelmesség: néha a szoba leírásához egy irányjelző hang-utalás társul.
// A kastély kőfalai torzíthatják a visszhangot - bizonyos szobatípusokban a jelzett irány NEM a valódi.
const ECHO_PRONE_ROOMS=new Set([10,11,20,21,34,35,36,40,43,44,45,46,47,48]);
const FOOTSTEP_FLAVORS=["Slow, dragging footsteps echo from the {dir}.","Something scrapes against stone from the {dir}.","A low growl drifts in from the {dir}.","You hear shallow, ragged breathing from the {dir}.","Claws click against the floor somewhere to the {dir}.","A heavy weight shifts, somewhere to the {dir}."];
function maybeGenerateThreatHint(id){if(gameState.pendingThreat&&(gameState.totalMoves||0)>gameState.pendingThreat.expiresAtMove){gameState.pendingThreat=null;}if(gameState.pendingThreat)return;const r=gameState.dungeon[id];if(!r)return;const forbidden=[0,49,gameState.blacksmithRoom,gameState.alchemistRoom,gameState.riddleSpiritRoom,...gameState.traderRooms,...gameState.mimicRooms];const baseChance=.22+Math.min(.18,(gameState.dread||0)*.002);if(Math.random()>baseChance)return;const neighbors=Object.entries(r.exits).filter(([dir,dest])=>typeof dest==="number"&&dest>=0&&!forbidden.includes(dest));if(!neighbors.length)return;const[realDir,realTarget]=neighbors[Math.floor(Math.random()*neighbors.length)];let hintDir=realDir;if(ECHO_PRONE_ROOMS.has(id)&&Math.random()<.4){const others=Object.keys(r.exits).filter(d=>d!==realDir&&typeof r.exits[d]==="number"&&r.exits[d]>=0);if(others.length)hintDir=others[Math.floor(Math.random()*others.length)];}const flavor=FOOTSTEP_FLAVORS[Math.floor(Math.random()*FOOTSTEP_FLAVORS.length)].replace("{dir}",hintDir);gameState.pendingThreat={fromRoom:id,realTarget,expiresAtMove:(gameState.totalMoves||0)+3};displayMessage(`<i>${flavor}</i>`,"error");}
const CALM_ROOM_FLAVORS=["The room feels a little calmer now than it did before.","Whatever unease lingered here before seems to have settled.","The air feels lighter here now.","Something about this place feels less watchful than it did."];
const HEAVY_TRAVEL_FLAVORS=["You trudge forward under the full weight of your pack.","Your gear clanks and drags with every step.","Exhaustion tugs at your shoulders as you press on.","You shift your load, breathing hard from the strain.","Every step feels heavier than the last."];
const HURT_TRAVEL_FLAVORS=["Blood seeps from a fresh cut as you press on.","You lean against the wall for a moment before continuing.","Your vision swims briefly before clearing.","Pain flares with every step you take.","You grit your teeth and keep moving despite the ache."];
function getTravelFlavor(){if(player.hp>0&&player.hp<=player.maxHP*.3&&Math.random()<.4)return HURT_TRAVEL_FLAVORS[Math.floor(Math.random()*HURT_TRAVEL_FLAVORS.length)];const load=getEncumbrancePenalties();if((load.label==="Very Heavy"||load.label==="Heavy")&&Math.random()<.35)return HEAVY_TRAVEL_FLAVORS[Math.floor(Math.random()*HEAVY_TRAVEL_FLAVORS.length)];return null;}

