function shuffle(arr){for(let i=arr.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]];}return arr;}
function clamp(v,min,max){return Math.max(min,Math.min(max,v));}

// --- DREAD METER ---
// A kastély "hangulata": kockázatos döntések és balul sikerült események emelik,
// idő (szobaváltás) lassan csökkenti. Magas dreadnél gyakoribbak és kicsit erősebbek a random enemyk.
function adjustDread(delta){const scaled=delta>0?delta*currentDifficultyDef().dreadMult:delta,before=gameState.dread||0;gameState.dread=clamp(before+scaled,0,100);if(delta>0){if(gameState.dread>=50&&!gameState.dreadWarned50){gameState.dreadWarned50=true;displayMessage("<i>Something about the castle feels different now. Heavier. Closer.</i>","error");}if(gameState.dread>=80&&!gameState.dreadWarned80){gameState.dreadWarned80=true;displayMessage("<i>The walls seem to lean in around you. You no longer feel like a guest here.</i>","error");}}}
function dreadLabel(){const d=gameState.dread||0;if(d<30)return"Calm";if(d<60)return"Tense";if(d<85)return"Dreadful";return"Suffocating";}

// --- SHAKEN STATUS (változatos riddle-büntetés: HP helyett néha ideiglenes teherbírás-csökkenés) ---
function applyShaken(rooms,amount){if(!Array.isArray(player.statusEffects))player.statusEffects=[];const existing=player.statusEffects.find(s=>s.type==="shaken");if(existing){player.maxWeight+=existing.amount;player.statusEffects=player.statusEffects.filter(s=>s.type!=="shaken");}player.maxWeight=Math.max(4,player.maxWeight-amount);player.statusEffects.push({type:"shaken",roomsLeft:rooms,amount});}
function tickStatusEffects(){if(!Array.isArray(player.statusEffects))player.statusEffects=[];player.statusEffects=player.statusEffects.filter(s=>{if(s.type==="shaken"){s.roomsLeft--;if(s.roomsLeft<=0){player.maxWeight+=s.amount;displayMessage("The shakiness in your hands fades. Your grip feels steady again.");return false;}}return true;});if(player.poisonTurns>0&&player.hp>0){const pd=Math.max(1,Math.ceil(player.maxHP*.05));player.hp-=pd;player.poisonTurns--;displayMessage(player.poisonTurns>0?`The poison burns in your blood as you move. You lose ${pd} HP.`:`The poison finally burns itself out. You lose ${pd} HP.`,"error");if(player.hp<=0)handlePlayerDeath("The poison finally takes you.");}}

// --- RATTLED (Banshee/Wailing Child sikoly): pár körig rontja a saját találati esélyed ---
function applyRattled(turns,amount){player.rattledTurns=turns;player.rattledAmount=amount;}

// --- LAST STAND: kritikus HP-nál egyszeri, run-onkénti adrenalin-bónusz, hogy a halál közeli pillanat drámaibb legyen ---
function checkLastStand(){if(player.lastStandUsed||player.hp<=0)return;if(player.hp<=Math.ceil(player.maxHP*.15)){player.lastStandUsed=true;player.lastStandTurns=2;displayMessage("<b>Something in you refuses to fall yet.</b> Adrenaline sharpens your next strikes.","header");}}
function normalizeText(v){return String(v||"").trim().toLowerCase();}
function canonicalItemName(input){const n=normalizeText(input);return Object.keys(ITEM_DEFS).find(x=>normalizeText(x)===n)||null;}
function getInventoryItem(name){const n=normalizeText(name);return player.inventory.find(it=>normalizeText(it.name)===n)||null;}
function getChestItem(name){const n=normalizeText(name);return player.chest.find(it=>normalizeText(it.name)===n)||null;}
function getTotalWeight(){return Number(player.inventory.reduce((s,it)=>s+((ITEM_DEFS[it.name]?.weight||1)*(it.qty||1)),0).toFixed(1));}
function getLoadRatio(){return player.maxWeight?getTotalWeight()/player.maxWeight:0;}
function getEncumbrancePenalties(){const r=getLoadRatio();if(r>=.95)return{miss:.10,flee:.18,damage:1,label:"Very Heavy"};if(r>=.80)return{miss:.05,flee:.10,damage:0,label:"Heavy"};if(r>=.60)return{miss:.02,flee:.04,damage:0,label:"Loaded"};return{miss:0,flee:0,damage:0,label:"Light"};}
function getWeaponInventoryItem(){return player.equipped.weapon?getInventoryItem(player.equipped.weapon):null;}
function getWeaponBonus(){const w=player.equipped.weapon;if(!w||!ITEM_DEFS[w])return 0;const d=ITEM_DEFS[w],m=(d.classBonus&&d.classBonus[player.class])||.5,wi=getWeaponInventoryItem(),u=wi?.upgrade||0,sharp=wi?.sharpen||0;return Math.floor(d.attack*m)+(u*2)+sharp;}
function canAddItem(name,qty=1){const d=ITEM_DEFS[name];if(!d)return{ok:false,reason:"Unknown item."};const found=getInventoryItem(name),limit=d.stack||1,current=found?(found.qty||1):0;if(current+qty>limit)return{ok:false,reason:`You can't carry more than ${limit} of ${name}.`};if(getTotalWeight()+d.weight*qty>player.maxWeight+.0001)return{ok:false,reason:"You are carrying too much weight."};return{ok:true};}
function addItem(name,qty=1,options={}){if(!ITEM_DEFS[name]){if(!options.silent)displayMessage(`Unknown item: ${name}`,"error");return false;}const c=canAddItem(name,qty);if(!c.ok){if(!options.silent)displayMessage(c.reason,"error");return false;}const found=getInventoryItem(name);if(found)found.qty=(found.qty||1)+qty;else player.inventory.push({name,qty,upgrade:0});renderStatusPanel();return true;}
function removeItem(name,qty=1){const n=normalizeText(name),idx=player.inventory.findIndex(it=>normalizeText(it.name)===n);if(idx===-1)return false;const item=player.inventory[idx],current=item.qty||1;if(current>qty)item.qty=current-qty;else{if(player.equipped.weapon&&normalizeText(player.equipped.weapon)===n)player.equipped.weapon=null;player.inventory.splice(idx,1);}renderStatusPanel();return true;}
function displayMessage(txt,style){const area=document.getElementById("game-text-output");if(!area)return;area.innerHTML+=`<p${style?` class="${style}"`:""}>${txt}</p>`;area.scrollTop=area.scrollHeight;}

function addToStash(name,qty=1,upgrade=0){const ex=getChestItem(name),d=ITEM_DEFS[name],limit=d?(d.stack||1):1;if(ex){if((ex.qty||1)+qty>limit)return false;ex.qty=(ex.qty||1)+qty;ex.upgrade=Math.max(ex.upgrade||0,upgrade||0);return true;}if(player.chest.length>=STASH_CAPACITY)return false;player.chest.push({name,qty,upgrade});return true;}
function removeFromStash(name,qty=1){const n=normalizeText(name),idx=player.chest.findIndex(it=>normalizeText(it.name)===n);if(idx===-1)return false;const item=player.chest[idx];if((item.qty||1)>qty)item.qty-=qty;else player.chest.splice(idx,1);return true;}
function takeRandomRoom(pool){if(!pool.length)return null;return pool.splice(Math.floor(Math.random()*pool.length),1)[0];}

function initDungeon(){
 gameState.dungeon=JSON.parse(JSON.stringify(ROOM_DEFS));gameState.bossRoom=49;gameState.activeShop=null;gameState.panelMode=null;gameState.towerRopeIntact=false;gameState.towerSecretEscape=false;gameState.gameEnded=false;gameState.riddleUsedIndexes=[];gameState.dread=0;gameState.dreadWarned50=false;gameState.dreadWarned80=false;gameState.totalMoves=0;gameState.pendingThreat=null;gameState.blacksmithWhetstoneStock=2;
 gameState.roomDepth=computeRoomDepths();
 gameState.roomCoords=computeRoomCoords();
 let earlyRooms=Array.from({length:28},(_,i)=>i+2);shuffle(earlyRooms);gameState.blacksmithRoom=takeRandomRoom(earlyRooms);gameState.alchemistRoom=takeRandomRoom(earlyRooms);const t1=takeRandomRoom(earlyRooms),t2=takeRandomRoom(earlyRooms);gameState.traderRooms=[t1,t2];gameState.possessedTraderRoom=Math.random()<.5?t1:t2;
 const forbidden=new Set([0,1,48,49,gameState.blacksmithRoom,gameState.alchemistRoom,...gameState.traderRooms]);let pool=Array.from({length:47},(_,i)=>i+1).filter(id=>!forbidden.has(id));shuffle(pool);
 gameState.giantMimicRoom=takeRandomRoom(pool);gameState.mimicRooms=[gameState.giantMimicRoom,takeRandomRoom(pool),takeRandomRoom(pool)];gameState.lootChestRooms=Array.from({length:6},()=>takeRandomRoom(pool));gameState.lockedChestRooms=Array.from({length:4},()=>takeRandomRoom(pool));gameState.heavyChestRooms=Array.from({length:2},()=>takeRandomRoom(pool));gameState.rustedChestRooms=Array.from({length:2},()=>takeRandomRoom(pool));gameState.emberChestRooms=Array.from({length:2},()=>takeRandomRoom(pool));gameState.riddleSpiritRoom=takeRandomRoom(pool);gameState.saveScrollRooms=[takeRandomRoom(pool),takeRandomRoom(pool)];
 let dark=Array.from({length:47},(_,i)=>i+2).filter(id=>id<49&&!forbidden.has(id));shuffle(dark);gameState.darkRooms=dark.slice(0,6);gameState.darkRooms.forEach(id=>{if(gameState.dungeon[id])gameState.dungeon[id].type="dark";});
 gameState.dungeon.forEach(room=>{room.loot=[];room.enemyDefeated=false;room.enemy=null;room.chestOpened=false;room.mimicDefeated=false;room.traderGreeted=false;});(gameState.saveScrollRooms||[]).forEach(id=>{if(gameState.dungeon[id])gameState.dungeon[id].loot.push("Save Scroll");});player.discovered={};player.location=0;player.previousLocation=0;player.discovered[0]=true;
}

function updateLegendVisibility(){const smith=document.getElementById("legend-smith"),alch=document.getElementById("legend-alch"),boss=document.getElementById("legend-boss");if(smith)smith.classList.toggle("hidden",!(gameState.blacksmithRoom!=null&&player.discovered[gameState.blacksmithRoom]));if(alch)alch.classList.toggle("hidden",!(gameState.alchemistRoom!=null&&player.discovered[gameState.alchemistRoom]));if(boss)boss.classList.toggle("hidden",!player.discovered[gameState.bossRoom]);}
function renderMap(){const coords=gameState.roomCoords||(gameState.roomCoords=computeRoomCoords());const ids=Object.keys(coords).map(Number);const m=document.getElementById("map-area");if(!ids.length){if(m)m.innerHTML="";updateLegendVisibility();return;}let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;const byPos={};ids.forEach(id=>{const c=coords[id];if(c.x<minX)minX=c.x;if(c.x>maxX)maxX=c.x;if(c.y<minY)minY=c.y;if(c.y>maxY)maxY=c.y;const key=`${c.x},${c.y}`;const existing=byPos[key];if(existing===undefined||(player.discovered[id]&&!player.discovered[existing])){byPos[key]=id;}});let out="";for(let y=minY;y<=maxY;y++){for(let x=minX;x<=maxX;x++){const id=byPos[`${x},${y}`];let ch=".";if(id===undefined||!player.discovered[id])ch=".";else if(player.location===id)ch='<span style="color:#00ffea;font-weight:bold;">P</span>';else if(id===gameState.blacksmithRoom)ch='<span style="color:#ff6060;">S</span>';else if(id===gameState.alchemistRoom)ch='<span style="color:#63ff85;">A</span>';else if(id===gameState.bossRoom)ch='<span style="color:#ffc700;">B</span>';else ch='<span style="color:#ffd966;">X</span>';out+=ch+" ";}out+="<br>";}if(m)m.innerHTML=out;updateLegendVisibility();}
function getRoomChestLabel(id){const r=gameState.dungeon[id];if(!r||r.chestOpened||r.mimicDefeated)return null;if(gameState.mimicRooms.includes(id)||gameState.lootChestRooms.includes(id))return"Chest";if(gameState.lockedChestRooms.includes(id))return"Locked Chest";if(gameState.heavyChestRooms.includes(id))return"Heavy Chest";if(gameState.rustedChestRooms.includes(id))return"Rusted Chest";if(gameState.emberChestRooms.includes(id))return"Ember Chest";return null;}
function getRoomLoot(id){const r=gameState.dungeon[id];if(!r)return[];let loot=Array.isArray(r.loot)?[...r.loot]:[];const c=getRoomChestLabel(id);if(c)loot.unshift(c);return loot;}
function getRoomNpcText(id){if(id===gameState.blacksmithRoom)return"<span style='color:#ff8a8a'><b>The Blacksmith is here.</b></span> Type <b>blacksmith</b> to speak with him.<br>";if(id===gameState.alchemistRoom)return"<span style='color:#8affaa'><b>The Alchemist is here.</b></span> Type <b>alchemist</b> to speak with her.<br>";if(gameState.traderRooms.includes(id)){if(id===gameState.possessedTraderRoom&&!player.possessedNpcDone)return"<span style='color:#b695d6'><b>A lone trader stands here with his back to you.</b></span><br>";return"<span style='color:#d6c27a'><b>A wandering Trader waits here.</b></span> Type <b>trader</b> to speak.<br>";}if(id===gameState.riddleSpiritRoom&&!player.riddleSpiritDone)return"<span style='color:#b695d6'><b>A pale spirit watches from the corner.</b></span><br>";return"";}
function displayRoom(id){const r=gameState.dungeon[id];if(!r)return;if(r.type==="dark"&&player.torchRoomsLeft<=0){displayMessage(`<span class="header">${r.name}</span><br>It is completely dark. You cannot see the room, its contents, or its exits.<br>You can still try a direction blindly, or use a <b>Torch</b>.`,`room`);return;}let txt=`<span class="header">${r.name}</span><br>${r.desc}<br>`+getRoomNpcText(id);const loot=getRoomLoot(id);if(loot.length)txt+=`<b>You see here:</b> ${loot.join(", ")}<br>`;txt+=`<b>Exits:</b> ${Object.keys(r.exits).join(", ")}<br>`;if((r.enemyDefeated||r.chestOpened||r.mimicDefeated)&&!r.calmNoted){r.calmNoted=true;txt+=`<span style="color:#9db38f;">${CALM_ROOM_FLAVORS[Math.floor(Math.random()*CALM_ROOM_FLAVORS.length)]}</span><br>`;}if(id===48)txt+="<span style='color:#d6c27a'>The final stairway is gone. A Rope may be the only way up.</span><br>";if(id===49&&!gameState.towerRopeIntact&&!gameState.towerSecretEscape)txt+="<span style='color:#ff9b9b'>The way down is broken. You may have to jump, or find another way.</span><br>";displayMessage(txt,"room");}
function recoverManaOnRoomMove(){if(player.class!=="mage"||player.mana>=player.maxMana)return;player.mana=Math.min(player.maxMana,player.mana+Math.max(1,Math.ceil(player.maxMana*.22)));}
function tickTorch(){if(player.torchRoomsLeft>0)player.torchRoomsLeft--;}
function moveToRoom(id){if(id<0||id>=gameState.dungeon.length){displayMessage("You cannot go that way.","error");return false;}player.previousLocation=player.location;player.location=id;player.discovered[id]=true;gameState.totalMoves=(gameState.totalMoves||0)+1;recoverManaOnRoomMove();tickTorch();tickStatusEffects();if(player.hp<=0)return false;adjustDread(-1);if(gameState.activeShop&&gameState.activeShop.summoned)gameState.activeShop=null;renderMap();displayRoom(id);const tf=getTravelFlavor();if(tf)displayMessage(`<i>${tf}</i>`);renderStatusPanel();triggerRoomEvents(id);return true;}
function triggerRoomEvents(id){if(gameState.gameEnded||inCombat||runtime.activeRiddle)return;if(id===gameState.possessedTraderRoom&&!player.possessedNpcDone){startPossessedNpcEvent();return;}if(id===gameState.riddleSpiritRoom&&!player.riddleSpiritDone){adjustDread(3);displayMessage("<i>The spirit raises one translucent hand. 'Three truths. Give me three truths, and I will give you something that should not exist.'</i>","riddle");startRiddleChallenge("spirit",3);return;}if(gameState.traderRooms.includes(id)&&id!==gameState.possessedTraderRoom&&!gameState.dungeon[id].traderGreeted){gameState.dungeon[id].traderGreeted=true;displayMessage("<i>The trader nods. 'Walls lie. Items don't. Keep the strange things you find.'</i>");}}

function renderStatusPanel(){const c=document.getElementById("status-panel-content");if(!c)return;const load=getEncumbrancePenalties(),wb=getWeaponBonus(),wi=getWeaponInventoryItem(),up=wi?(wi.upgrade||0):0;let s=`<b>Name:</b> ${player.name} (${player.gender}, ${player.className})<br>`;s+=`<b>Difficulty:</b> ${currentDifficultyDef().label}<br>`;s+=`<b>HP:</b> ${player.hp}/${player.maxHP} &nbsp; <b>Mana:</b> ${player.mana}/${player.maxMana}<br>`;s+=`<b>Gold:</b> ${player.gold} &nbsp; <b>XP:</b> ${player.xp} &nbsp; <b>Level:</b> ${player.level}<br>`;s+=`<b>Weight:</b> ${getTotalWeight()}/${player.maxWeight} (${load.label})<br>`;s+=`<b>Weapon:</b> ${player.equipped.weapon||"None"}`;if(player.equipped.weapon)s+=` <span style="color:#ffe68a;">(+${wb} attack${up?`, +${up} upgrade`:""})</span>`;s+="<br>";s+=`<b>Attack:</b> ${player.attack+wb} &nbsp; <b>Defense:</b> ${player.defense}<br>`;s+=`<b>Luck:</b> ${player.luck} &nbsp; <b>Flee:</b> ${Math.round(player.fleeChance*100)}%<br>`;s+=`<b>Castle Mood:</b> ${dreadLabel()}<br>`;if(player.statPoints>0)s+=`<span style="color:#fac858;"><b>Unspent level points:</b> ${player.statPoints}</span><br>`;s+=player.poisonTurns>0?`<span style="color:#88d36b;"><b>Status:</b> Poisoned (fades in ${player.poisonTurns} room${player.poisonTurns===1?"":"s"})</span><br>`:'<b>Status:</b> Normal<br>';if(player.rattledTurns>0)s+='<span style="color:#ffb3b3;"><b>Rattled:</b> aim thrown off</span><br>';if(player.lastStandTurns>0)s+='<span style="color:#ffe68a;"><b>Adrenaline:</b> striking harder</span><br>';if(player.torchRoomsLeft>0)s+=`<b>Torch:</b> ${player.torchRoomsLeft} moves of light<br>`;c.innerHTML=s;}
function renderInventoryPanel(){const sp=document.getElementById("status-panel-content"),ip=document.getElementById("inventory-panel-content"),p=document.getElementById("inventory-panel");if(!sp||!ip||!p)return;sp.style.display="none";p.classList.add("active");gameState.panelMode="inventory";let out="<h4>Inventory</h4><ul>";if(!player.inventory.length)out+="<li>(empty)</li>";for(const it of player.inventory)out+=`<li>${it.name}${it.upgrade?` +${it.upgrade}`:""} x${it.qty||1}</li>`;out+=`</ul><p>Weight: ${getTotalWeight()}/${player.maxWeight}</p><button onclick="exitInventoryPanel()">Exit</button>`;ip.innerHTML=out;}
function exitInventoryPanel(){const p=document.getElementById("inventory-panel"),s=document.getElementById("status-panel-content");if(p)p.classList.remove("active");if(s)s.style.display="";gameState.panelMode=null;}
function canAccessStash(){return !!gameState.activeShop||player.location===gameState.blacksmithRoom||player.location===gameState.alchemistRoom;}
function renderStashPanel(){if(!canAccessStash()){displayMessage("The shared stash can only be accessed at the Blacksmith, the Alchemist, or a summoned shop.","error");return;}const sp=document.getElementById("status-panel-content"),ip=document.getElementById("inventory-panel-content"),p=document.getElementById("inventory-panel");if(!sp||!ip||!p)return;sp.style.display="none";p.classList.add("active");gameState.panelMode="stash";let out=`<h4>Shared Stash (${player.chest.length}/${STASH_CAPACITY} slots)</h4><ul>`;if(!player.chest.length)out+="<li>(empty)</li>";for(const it of player.chest)out+=`<li>${it.name}${it.upgrade?` +${it.upgrade}`:""} x${it.qty||1}</li>`;out+="</ul><p>Commands: <b>store [item]</b>, <b>retrieve [item]</b></p><button onclick=\"exitInventoryPanel()\">Exit</button>";ip.innerHTML=out;}
function handleStoreCommand(name){if(!canAccessStash()){displayMessage("You cannot access the stash here.","error");return;}const it=getInventoryItem(name);if(!it){displayMessage("You do not have that item.","error");return;}if(ITEM_DEFS[it.name]?.type==="legendarykey"){displayMessage("The legendary key refuses to leave your possession.","error");return;}if(!addToStash(it.name,1,it.upgrade||0)){displayMessage("The stash is full, or that stack cannot hold more.","error");return;}removeItem(it.name,1);displayMessage(`You store ${it.name}.`);renderStashPanel();}
function handleRetrieveCommand(name){if(!canAccessStash()){displayMessage("You cannot access the stash here.","error");return;}const it=getChestItem(name);if(!it){displayMessage("That item is not in the stash.","error");return;}const c=canAddItem(it.name,1);if(!c.ok){displayMessage(c.reason,"error");return;}const up=it.upgrade||0;addItem(it.name,1,{silent:true});const inv=getInventoryItem(it.name);if(inv)inv.upgrade=Math.max(inv.upgrade||0,up);removeFromStash(it.name,1);displayMessage(`You retrieve ${it.name}.`);renderStashPanel();}

function handleTakeCommand(name){const n=normalizeText(name);if(["chest","locked chest","heavy chest","rusted chest","ember chest"].includes(n)){displayMessage("You cannot carry the chest. Try <b>open [chest]</b>.","error");return;}const r=gameState.dungeon[player.location],idx=(r.loot||[]).findIndex(x=>normalizeText(x)===n);if(idx===-1){displayMessage("There is no such loose item here.","error");return;}const item=r.loot[idx];if(!addItem(item,1))return;r.loot.splice(idx,1);displayMessage(`You take the ${item}.`);if(item==="Tempered Ore"&&!player.seenTemperedOreLore){player.seenTemperedOreLore=true;displayMessage("<i>The ore is unusually dense and warm. A skilled smith could turn this into a serious weapon upgrade.</i>");}displayRoom(player.location);}
function lockpickBreakChance(){return player.class==="rogue"?.20:.35;}
function tryUseLockpick(){if(!getInventoryItem("Lockpick")){displayMessage("You need a Lockpick.","error");return false;}if(Math.random()<lockpickBreakChance()){removeItem("Lockpick",1);displayMessage("The Lockpick snaps inside the mechanism!","error");}else displayMessage("The Lockpick survives the attempt.");return true;}
function ropeBreakChance(){const r=getLoadRatio();if(r>=.95)return .65;if(r>=.80)return .50;if(r>=.60)return .35;return .20;}
function resolveRopeUse(context="normal"){if(!getInventoryItem("Rope")){displayMessage("You need a Rope.","error");return{used:false,broke:false};}const broke=Math.random()<ropeBreakChance();if(broke){removeItem("Rope",1);adjustDread(6);displayMessage(context==="tower"?"You reach the top just as the Rope tears free and vanishes into the darkness below!":"The Rope snaps after taking your weight!","error");}else displayMessage("The Rope holds.");return{used:true,broke};}
function generateCommonLoot(){const pool=["Potion HP","Potion Mana","Lockpick","Torch","Herb","Crystal","Mushroom","Water","Oil Can","Rope","Map Fragment"];return pool[Math.floor(Math.random()*pool.length)];}
function generateChestLoot(id){const r=gameState.dungeon[id];if(!r.loot)r.loot=[];const primary=generateCommonLoot();r.loot.push(primary);const roll=Math.random();if(roll<.05)r.loot.push("Tempered Ore");else if(roll<.08)r.loot.push("Mirror Shard");else if(roll<.11)r.loot.push("Ancient Rune");else if(roll<.14)r.loot.push("Silver Key");else if(roll<.18)r.loot.push("Strange Coin");else if(roll<.20)r.loot.push("Blood-Bound Blade");let gold=0;if(Math.random()<.35){gold=Math.max(1,Math.round((4+Math.floor(Math.random()*10))*currentDifficultyDef().goldMult));player.gold+=gold;}return{primary,gold};}
function openNormalChest(){const r=gameState.dungeon[player.location];if(r.chestOpened){displayMessage("The chest is already empty.");return;}const res=generateChestLoot(player.location);r.chestOpened=true;displayMessage(`You open the chest. Inside: <b>${res.primary}</b>${res.gold?` and ${res.gold} gold`:""}.`);displayRoom(player.location);}
function handleOpenItemCommand(name){const item=normalizeText(name),label=getRoomChestLabel(player.location);if(!label||normalizeText(label)!==item){displayMessage("There is no such object to open here.","error");return;}const id=player.location,r=gameState.dungeon[id];if(gameState.mimicRooms.includes(id)&&!r.mimicDefeated){displayMessage("The lid twitches under your hand. Teeth unfold from the wood.","error");mimicEvent();return;}if(gameState.lockedChestRooms.includes(id)){if(!tryUseLockpick())return;openNormalChest();return;}if(gameState.heavyChestRooms.includes(id)){if(!getInventoryItem("Crowbar")){displayMessage("The lid will not move. You need a Crowbar.","error");return;}displayMessage("You wedge the Crowbar under the lid and force it open.");openNormalChest();return;}if(gameState.rustedChestRooms.includes(id)){if(!getInventoryItem("Oil Can")){displayMessage("The mechanism is fused with rust. An Oil Can might help.","error");return;}removeItem("Oil Can",1);displayMessage("Oil creeps into the rusted lock. With a reluctant click, it releases.");openNormalChest();return;}if(gameState.emberChestRooms.includes(id)){if(!getInventoryItem("Bucket of Water")){displayMessage("Heat rolls off the chest. You need a Bucket of Water to cool the seal.","error");return;}removeItem("Bucket of Water",1);displayMessage("Steam fills the room as you douse the glowing seal. The metal finally cools.");openNormalChest();return;}openNormalChest();}

function handleUseCommand(name){const it=getInventoryItem(name);if(!it){displayMessage("You do not have that item.","error");return false;}const d=ITEM_DEFS[it.name];if(!d)return false;
 if(d.type==="potion"){if(d.effect==="heal"){if(player.hp>=player.maxHP){displayMessage("You are already at full HP.","error");return false;}player.hp=Math.min(player.maxHP,player.hp+11);removeItem(it.name,1);displayMessage("Warmth returns to your limbs.");renderStatusPanel();return true;}if(d.effect==="mana"){if(player.mana>=player.maxMana){displayMessage("Your mana is already full.","error");return false;}player.mana=Math.min(player.maxMana,player.mana+8);removeItem(it.name,1);displayMessage("Arcane energy rushes back into you.");renderStatusPanel();return true;}if(d.effect==="luck"){player.luck=Math.min(10,player.luck+1);removeItem(it.name,1);displayMessage("For a moment, the castle feels slightly less certain of itself.");renderStatusPanel();return true;}if(d.effect==="antidote"){if(player.poisonTurns<=0){displayMessage("You are not poisoned.","error");return false;}player.poisonTurns=0;removeItem(it.name,1);displayMessage("The poison fades.");renderStatusPanel();return true;}}
 if(normalizeText(it.name)==="torch"){removeItem("Torch",1);player.torchRoomsLeft=5;displayMessage("You light the Torch. The dark pulls back.");displayRoom(player.location);renderStatusPanel();return true;}
 if(normalizeText(it.name)==="whetstone"){const wi=getWeaponInventoryItem();if(!wi){displayMessage("You have no weapon equipped to sharpen.","error");return false;}const wd=ITEM_DEFS[wi.name];if(!wd||wd.type==="legendary"){displayMessage("A whetstone can't improve a weapon like this.","error");return false;}const sharp=wi.sharpen||0;if(sharp>=2){displayMessage(`Your ${wi.name} is already as sharp as a whetstone can make it.`,"error");return false;}wi.sharpen=sharp+1;removeItem("Whetstone",1);displayMessage(`You hone the edge of your ${wi.name}. (+1 attack, permanent)`);renderStatusPanel();return true;}
 if(normalizeText(it.name)==="summon blacksmith"){removeItem("Summon Blacksmith",1);openShop("blacksmith",true);return true;}
 if(normalizeText(it.name)==="summon alchemist"){removeItem("Summon Alchemist",1);openShop("alchemist",true);return true;}
 if(normalizeText(it.name)==="rope"&&player.location===18&&!player.wellSecret){const res=resolveRopeUse("well");if(!res.used)return false;player.wellSecret=true;gameState.dungeon[18].loot.push("Map Fragment");displayMessage("You descend into the well and find a narrow ledge. Something wrapped in oilcloth rests there: <b>Map Fragment</b>.");return true;}
 if(normalizeText(it.name)==="mirror shard"){if(player.location===40&&!player.hallOfMirrorsSecret){player.hallOfMirrorsSecret=true;gameState.dungeon[40].loot.push(Math.random()<.5?"Tempered Ore":"Map Fragment");displayMessage("You raise the Mirror Shard. One reflection vanishes, revealing a hidden recess behind the glass.");displayRoom(40);return true;}if(player.location===49&&!gameState.towerRopeIntact){gameState.towerSecretEscape=true;displayMessage("The Mirror Shard catches light from nowhere. A reflected doorway appears in the stone, leading safely downward.");moveToRoom(48);return true;}displayMessage("The Mirror Shard reflects nothing useful here.");return false;}
 if(normalizeText(it.name)==="ancient rune"){if((player.location===42||player.location===43)&&!player.runeSecret){player.runeSecret=true;removeItem("Ancient Rune",1);gameState.dungeon[player.location].loot.push("Tempered Ore");displayMessage("The Ancient Rune answers the symbols in the stone. A hidden compartment opens with a deep mechanical sigh.");displayRoom(player.location);return true;}if(player.location===49&&!gameState.towerRopeIntact){removeItem("Ancient Rune",1);gameState.towerSecretEscape=true;displayMessage("The Rune flares. Transparent steps form along the outer wall, carrying you safely down.");moveToRoom(48);return true;}displayMessage("The Ancient Rune remains cold.");return false;}
 if(normalizeText(it.name)==="silver key"){if(player.location===41&&!player.silverSecret){player.silverSecret=true;removeItem("Silver Key",1);gameState.dungeon[41].loot.push(Math.random()<.4?"Tempered Ore":(Math.random()<.5?"Meteorite Sword":"Shadow Bow"));displayMessage("The Silver Key fits a lock hidden behind the bleeding painting. A narrow cache opens.");displayRoom(41);return true;}displayMessage("The Silver Key fits nothing here.");return false;}
 if(normalizeText(it.name)==="strange coin"){if(!gameState.traderRooms.includes(player.location)){displayMessage("The Strange Coin grows warm, but no one answers.","error");return false;}if(player.secretTraderUsed){displayMessage("The coin is dull now. Whatever heard it has already come.");return false;}removeItem("Strange Coin",1);player.secretTraderUsed=true;openShop("secret",false);return true;}
 if(normalizeText(it.name)==="map fragment"){const frag=getInventoryItem("Map Fragment");if(!frag||(frag.qty||1)<3){displayMessage("The fragments do not form a complete map yet.","error");return false;}if(player.location!==33){displayMessage("The fragments show a hidden mark, but this is not the place.","error");return false;}if(player.mapSecret){displayMessage("You already opened the hidden route.");return false;}removeItem("Map Fragment",3);player.mapSecret=true;gameState.dungeon[33].loot.push("Tempered Ore");if(Math.random()<.25)grantRandomLegendaryKey("the completed secret map");displayMessage("The three fragments align with the alcove wall. A false stone slides aside, revealing a hidden cache.");displayRoom(33);return true;}
 displayMessage("You cannot find a useful way to use that here.","error");return false;
}

function scaleEnemy(base){const d=currentDifficultyDef(),lvl=Math.max(1,player.level),e={...base};e.hp=Math.round(base.hp*(1+.32*(lvl-1))*d.enemyHpMult);e.maxHP=e.hp;e.attack=Math.round((base.attack+Math.floor((lvl-1)*1.15))*d.enemyAtkMult);e.defense=base.defense+Math.floor((lvl-1)/2);e.xp=base.xp+Math.floor((lvl-1)*1.5);return e;}
function spawnEnemy(id){if(id===0||id===49||id===gameState.blacksmithRoom||id===gameState.alchemistRoom||gameState.traderRooms.includes(id)||gameState.mimicRooms.includes(id)||id===gameState.riddleSpiritRoom)return null;const r=gameState.dungeon[id];if(!r)return null;if(r.enemyDefeated){const stale=(gameState.totalMoves||0)-(r.clearedAtMove||0);if(stale<25||Math.random()>.15)return null;r.enemyDefeated=false;}const d=currentDifficultyDef(),dreadBonus=Math.min(.15,(gameState.dread||0)*.0015);if(Math.random()>clamp((.14+dreadBonus)*d.spawnMult,.04,.90))return null;const pool=getZonePool(id),base=pool[Math.floor(Math.random()*pool.length)],e=scaleEnemy(base);if((gameState.dread||0)>=70)e.attack+=1;if(d.packChance>0&&Math.random()<d.packChance){const base2=pool[Math.floor(Math.random()*pool.length)];e.partner=scaleEnemy(base2);}r.enemy=e;return e;}
function startCombat(enemy){currentEnemy=enemy;inCombat=true;recordEnemySeen(enemy.name);const partnerHint=enemy.partner?"<br><i>Something else moves in the shadows behind it.</i>":"";displayMessage(`<b>Combat!</b> ${enemy.name} — HP ${enemy.hp}${partnerHint}<br>Commands: <b>attack</b>, <b>use [item]</b>, <b>equip [weapon]</b>, <b>flee</b>, <b>inventory</b>`,`header`);renderStatusPanel();}
function enemyStrike(e,label){if(!e||player.hp<=0)return;if(e.charges){if(!e.charging){e.charging=true;displayMessage(`The ${label} begins to channel dark energy...`,"error");return;}e.charging=false;const dmg=Math.max(1,(e.attack*2)-player.defense+getEncumbrancePenalties().damage);player.hp-=dmg;displayMessage(`The ${label} unleashes the channeled attack for ${dmg} damage!`,"error");return;}if(e.scream&&Math.random()<.35){applyRattled(2,.15);displayMessage(`The ${label} lets out a piercing scream. Your ears ring.`,"error");return;}if(Math.random()<(e.miss||.10)){displayMessage(`The ${label} misses you!`);return;}let dmg=Math.max(1,e.attack-player.defense+getEncumbrancePenalties().damage);player.hp-=dmg;displayMessage(`The ${label} hits you for ${dmg} damage.`);if(e.lifesteal){const heal=Math.max(1,Math.round(dmg*e.lifesteal));e.hp=Math.min(e.maxHP,e.hp+heal);displayMessage(`The ${label} drains ${heal} HP from you.`,"error");}if(e.poisonChance&&Math.random()<e.poisonChance){if(player.poisonTurns<=0)displayMessage("Poison seeps into your blood.","error");player.poisonTurns=2;}}
function handlePlayerDeath(msg){player.hp=0;inCombat=false;currentEnemy=null;gameState.gameEnded=true;displayMessage(`${msg} <b>GAME OVER.</b><br>Use <b>load</b> or <b>reset</b>.`,"error");renderStatusPanel();}
function enemyTurn(){if(!inCombat||!currentEnemy)return;enemyStrike(currentEnemy,currentEnemy.name);if(player.hp<=0){loseCombat();return;}if(currentEnemy.partner){enemyStrike(currentEnemy.partner,`${currentEnemy.partner.name} (lurking nearby)`);if(player.hp<=0){loseCombat();return;}}checkLastStand();}
function processCombatCommand(raw){if(!inCombat||!currentEnemy){displayMessage("No combat is active.","error");return;}const cmd=normalizeText(raw);if(cmd==="attack"){let wb=getWeaponBonus(),note="";if(player.class==="mage"){if(player.mana>0){player.mana--;note=" (-1 mana)";}else{wb=Math.floor(wb*.25);note=" (no mana — weakened attack)";}}const rattled=player.rattledTurns>0,lastStand=player.lastStandTurns>0;const miss=clamp(player.missChance+getEncumbrancePenalties().miss-player.luck*.004+(rattled?player.rattledAmount:0)-(lastStand?.08:0),.03,.60);if(Math.random()<miss)displayMessage(`You attack and miss!${note}${rattled?" (ears still ringing)":""}`,"error");else{const dmg=Math.max(1,player.attack+wb+Math.floor(Math.random()*3)-currentEnemy.defense+(lastStand?2:0));currentEnemy.hp-=dmg;const wDefHit=ITEM_DEFS[player.equipped.weapon];let healNote="";if(wDefHit&&wDefHit.lifesteal&&player.hp<player.maxHP){const heal=Math.max(1,Math.round(dmg*wDefHit.lifesteal));player.hp=Math.min(player.maxHP,player.hp+heal);healNote=` (+${heal} HP)`;}displayMessage(`You hit the ${currentEnemy.name} for ${dmg} damage.${note}${lastStand?" (adrenaline)":""}${healNote}`);}const wDef=ITEM_DEFS[player.equipped.weapon];if(wDef&&wDef.cursed)adjustDread(1);if(rattled)player.rattledTurns--;if(lastStand)player.lastStandTurns--;if(currentEnemy.hp<=0){winCombat();return;}enemyTurn();if(inCombat&&currentEnemy)displayMessage(`<b>${currentEnemy.name}</b> HP: ${currentEnemy.hp} — Your HP: ${player.hp}`,"header");renderStatusPanel();return;}if(cmd.startsWith("use ")){const used=handleUseCommand(cmd.slice(4));if(used&&inCombat&&currentEnemy)enemyTurn();renderStatusPanel();return;}if(cmd.startsWith("equip ")){handleEquipCommand(cmd.slice(6));if(inCombat&&currentEnemy)enemyTurn();renderStatusPanel();return;}if(cmd==="inventory"||cmd==="inv"){renderInventoryPanel();return;}if(cmd==="flee"){const enc=getEncumbrancePenalties(),fails=currentEnemy.fleeFails||0,chance=clamp(player.fleeChance+player.luck*.008-enc.flee-fails*.02,.14,.80);if(Math.random()<chance){displayMessage(`You escape! (${Math.round(chance*100)}% chance)`);inCombat=false;currentEnemy=null;player.rattledTurns=0;const back=player.previousLocation;if(back!==player.location&&back>=0&&back<gameState.dungeon.length)moveToRoom(back);else displayRoom(player.location);return;}currentEnemy.fleeFails=fails+1;displayMessage(`You fail to escape${fails>=2?", growing more exhausted with each attempt":""}. (${Math.round(chance*100)}% chance)`,`error`);enemyTurn();renderStatusPanel();return;}displayMessage("Unknown combat command. Use attack, use [item], equip [weapon], flee, inventory.","error");}
function recoverManaAfterCombat(){if(player.class!=="mage")return;player.mana=Math.min(player.maxMana,player.mana+Math.max(1,Math.ceil(player.maxMana*.20)));}
function winCombat(){const e=currentEnemy;if(!e)return;displayMessage(`You defeated the ${e.name}!`,`header`);const gold=Math.max(1,Math.round((1+Math.floor(Math.random()*4)+Math.floor((player.level-1)/3))*currentDifficultyDef().goldMult));player.gold+=gold;player.xp+=Math.round((e.xp||1)*(CLASS_DEFS[player.class]?.xpMultiplier||1));displayMessage(`You recover ${gold} gold.`);tryLevelUp();if(e.partner){const next=e.partner;currentEnemy=next;displayMessage(`<b>The ${next.name} lunges out of hiding to take its place!</b>`,"error");renderStatusPanel();return;}const r=gameState.dungeon[player.location];if(e.isMimic){r.mimicDefeated=true;const kc=e.isGiant?.30:.08,oc=e.isGiant?.28:.10;if(Math.random()<kc)grantRandomLegendaryKey(e.isGiant?"the Giant Mimic":"the Mimic");if(Math.random()<oc){r.loot.push("Tempered Ore");displayMessage("Something dense and dark clatters from the Mimic: <b>Tempered Ore</b>.");}if(Math.random()<.55){const drop=generateCommonLoot();r.loot.push(drop);displayMessage(`The Mimic leaves behind: <b>${drop}</b>.`);}}else{r.enemyDefeated=true;r.clearedAtMove=gameState.totalMoves||0;if(Math.random()<.22){const drop=generateCommonLoot();r.loot.push(drop);displayMessage(`You notice ${drop} on the floor.`);}}inCombat=false;currentEnemy=null;player.rattledTurns=0;recoverManaAfterCombat();if(runtime.endingType==="meteorite"){displayMessage("<b>Xykon falls.</b><br>The Meteorite Key cracks in your hand as the dragon's fire goes dark. Dawn reaches the castle for the first time in generations.","header");endGame();return;}renderStatusPanel();displayRoom(player.location);}
function loseCombat(){handlePlayerDeath("You have been defeated.");}
function mimicEvent(){const giant=player.location===gameState.giantMimicRoom,base=giant?{name:"Giant Mimic",hp:20,attack:6,defense:4,xp:22,miss:.14}:{name:"Mimic",hp:14,attack:5,defense:3,xp:13,miss:.16},m=scaleEnemy(base);m.isMimic=true;m.isGiant=giant;adjustDread(giant?7:5);displayMessage(`The Chest splits open into a ${giant?"GIANT MIMIC":"MIMIC"}!`,`header`);startCombat(m);}
function handleEquipCommand(name){const it=getInventoryItem(name);if(!it){displayMessage("You do not have that weapon.","error");return false;}const d=ITEM_DEFS[it.name];if(!d||!["weapon","legendary"].includes(d.type)){displayMessage("That is not a weapon.","error");return false;}player.equipped.weapon=it.name;displayMessage(`You equip ${it.name}.`);renderStatusPanel();return true;}

function tryLevelUp(){let changed=false;while(true){const req=Math.round(7*Math.pow(player.level,1.25)+8);if(player.xp<req)break;player.xp-=req;player.level++;player.statPoints++;changed=true;displayMessage(`<b>LEVEL UP!</b> You are now level ${player.level}.<br>Choose one improvement with <b>levelup hp</b>, <b>levelup attack</b>, <b>levelup defense</b>, <b>levelup mana</b>, <b>levelup weight</b>, <b>levelup luck</b>, or <b>levelup flee</b>.`,`header`);if(player.level===5||player.level===10){player.statPoints++;displayMessage(`<i>Something about surviving this long feels like it should count for more.</i> <b>Bonus level point!</b>`,"header");}}if(changed)renderStatusPanel();}
function handleLevelUpChoice(stat){if(player.statPoints<=0){displayMessage("You have no unspent level points.","error");return;}switch(normalizeText(stat)){case"hp":player.maxHP+=4;player.hp=Math.min(player.maxHP,player.hp+4);break;case"attack":player.attack++;break;case"defense":player.defense++;break;case"mana":player.maxMana+=2;player.mana=Math.min(player.maxMana,player.mana+2);break;case"weight":case"maxweight":player.maxWeight++;break;case"luck":player.luck=Math.min(10,player.luck+1);break;case"flee":player.fleeChance=clamp(player.fleeChance+.04,0,.80);break;default:displayMessage("Unknown stat. Choose hp, attack, defense, mana, weight, luck, or flee.","error");return;}player.statPoints--;displayMessage(`Your ${stat} improves.`);renderStatusPanel();}

function pickRiddle(){if(gameState.riddleUsedIndexes.length>=RIDDLE_BANK.length)gameState.riddleUsedIndexes=[];let idx;do{idx=Math.floor(Math.random()*RIDDLE_BANK.length);}while(gameState.riddleUsedIndexes.includes(idx));gameState.riddleUsedIndexes.push(idx);return RIDDLE_BANK[idx];}
function startRiddleChallenge(context,requiredCorrect){runtime.activeRiddle={context,requiredCorrect,correct:0,current:pickRiddle()};displayMessage(`<b>Riddle 1/${requiredCorrect}</b><br>${runtime.activeRiddle.current.q}<br>Type: <b>answer [your answer]</b>`,`riddle`);}
function normalizeAnswer(a){return normalizeText(a).replace(/^\d+\s+/,"");}
function answerMatches(r,a){const n=normalizeAnswer(a);return r.a.some(v=>normalizeText(v)===n);}
function stealRandomNonQuestItem(){const c=player.inventory.filter(it=>{const d=ITEM_DEFS[it.name];return !d||!["legendarykey","scroll"].includes(d.type);});if(!c.length)return null;const chosen=c[Math.floor(Math.random()*c.length)],name=chosen.name;removeItem(name,1);return name;}
function riddlePenalty(context){if(context==="possessed"){const roll=Math.random();if(roll<.45){const lost=stealRandomNonQuestItem();if(lost){displayMessage(`The entity smiles. Something vanishes from your pack: <b>${lost}</b>.`,`error`);adjustDread(5);return;}}if(roll<.75){const dmg=Math.max(1,Math.ceil(player.maxHP*.25));player.hp=Math.max(1,player.hp-dmg);displayMessage(`With nothing useful to steal, the entity takes ${dmg} HP instead.`,`error`);adjustDread(5);return;}applyShaken(5,3);displayMessage("The entity's laughter rattles your bones. Your hands will not stop trembling. <i>(Carry capacity reduced for a while.)</i>","error");adjustDread(5);return;}const pct=context==="shadowEnding"?.15:.10,roll2=Math.random();if(roll2<.65){const dmg=Math.max(1,Math.ceil(player.maxHP*pct));player.hp=Math.max(1,player.hp-dmg);displayMessage(`The answer was wrong. You lose ${dmg} HP.`,`error`);}else{applyShaken(4,2);displayMessage("The wrong answer costs you more than pride. Your hands shake. <i>(Carry capacity reduced for a while.)</i>","error");}adjustDread(context==="shadowEnding"?6:4);}
function completeRiddleChallenge(context){runtime.activeRiddle=null;adjustDread(-5);if(context==="possessed"){player.possessedNpcDone=true;displayMessage("<i>The trader convulses. A ribbon of black smoke tears itself from his mouth and vanishes into the ceiling.</i><br>He falls to his knees, alive but confused.","header");grantRandomLegendaryKey("the banished entity");return;}if(context==="spirit"){player.riddleSpiritDone=true;displayMessage("<i>The spirit bows. 'Truth deserves a door.'</i>","header");grantRandomLegendaryKey("the Riddle Spirit");return;}if(context==="shadowEnding"){displayMessage("<b>The final answer echoes through the dark.</b><br>The shadows turn upon themselves, devouring the curse that bound the tower.<br><b>Shadow Ending</b>","header");endGame();}}
function handleAnswerCommand(answer){const c=runtime.activeRiddle;if(!c){displayMessage("There is no riddle to answer.","error");return;}if(answerMatches(c.current,answer)){c.correct++;displayMessage(`Correct. (${c.correct}/${c.requiredCorrect})`,`header`);if(c.correct>=c.requiredCorrect){completeRiddleChallenge(c.context);renderStatusPanel();return;}c.current=pickRiddle();displayMessage(`<b>Riddle ${c.correct+1}/${c.requiredCorrect}</b><br>${c.current.q}<br>Type: <b>answer [your answer]</b>`,`riddle`);return;}displayMessage("Wrong answer.","error");riddlePenalty(c.context);c.current=pickRiddle();displayMessage(`<b>Try again.</b><br>${c.current.q}<br>Type: <b>answer [your answer]</b>`,`riddle`);renderStatusPanel();}
function startPossessedNpcEvent(){adjustDread(3);displayMessage("<i>The trader turns. His eyes are completely black.</i><br>'Three answers,' a second voice says through his mouth. 'Until then, you belong to this room.'","riddle");startRiddleChallenge("possessed",3);}
function grantRandomLegendaryKey(source){const missing=LEGENDARY_KEYS.filter(k=>!getInventoryItem(k.name));if(!missing.length){if(addItem("Tempered Ore",1))displayMessage(`${source} leaves behind <b>Tempered Ore</b> instead.`);return;}const key=missing[Math.floor(Math.random()*missing.length)];if(addItem(key.name,1))displayMessage(`A strange weight settles into your hand: <b>${key.name}</b>. It came from ${source}.`,`header`);else{gameState.dungeon[player.location].loot.push(key.name);displayMessage(`<b>${key.name}</b> falls to the floor.`,`header`);}}

function shopPrice(base,summoned){return Math.ceil(base*(summoned?1.10:1));}
function shopGreeting(type,summoned){if(type==="blacksmith"){if(summoned)return"<i>The Blacksmith appears in a shower of sparks. 'You couldn't walk back yourself? Fine. Make it quick.'</i><br>";if(!player.blacksmithGreeted){player.blacksmithGreeted=true;addItem("Summon Blacksmith",1,{silent:true});return"<i>The Blacksmith looks up from the anvil. 'You're either brave or stupid. Probably both. Here—if you get yourself trapped somewhere, burn this scroll and I'll come to you. Don't make a habit of it.'</i><br><b>You receive: Summon Blacksmith.</b><br>";}return"<i>The Blacksmith grunts. 'You again? What did you break this time?'</i><br>";}if(type==="alchemist"){if(summoned)return"<i>The Alchemist appears holding a bottle that is still bubbling. 'Again? I was in the middle of something expensive.'</i><br>";if(!player.alchemistGreeted){player.alchemistGreeted=true;addItem("Summon Alchemist",1,{silent:true});return"<i>The Alchemist studies you for a long moment. 'A living customer. How unusual. Take this scroll. If you bleed somewhere inconvenient, call me before you die.'</i><br><b>You receive: Summon Alchemist.</b><br>";}return"<i>The Alchemist raises an eyebrow. 'Back already? Try not to drink everything at once.'</i><br>";}if(type==="secret")return"<i>The Strange Coin turns black. A hooded merchant steps out of a shadow that was not there before. 'One visit. Choose carefully.'</i><br>";return"";}
function openShop(type,summoned=false){if(type==="blacksmith"&&!summoned&&player.location!==gameState.blacksmithRoom){displayMessage("The Blacksmith is not here.","error");return;}if(type==="alchemist"&&!summoned&&player.location!==gameState.alchemistRoom){displayMessage("The Alchemist is not here.","error");return;}if(type==="secret"&&!gameState.traderRooms.includes(player.location)){displayMessage("No secret trader answers here.","error");return;}gameState.activeShop={type,summoned};let txt=shopGreeting(type,summoned);if(type==="blacksmith"){txt+="<b>Blacksmith Shop</b><br>Weapons and tools only. No potions, recipes, or alchemy materials.<br>";for(const [item,base] of Object.entries(BLACKSMITH_BUY)){if(item==="Whetstone"){txt+=`Buy Whetstone — ${shopPrice(base,summoned)}g <i>(${gameState.blacksmithWhetstoneStock} left this run)</i><br>`;continue;}txt+=`Buy ${item} — ${shopPrice(base,summoned)}g<br>`;}txt+=`<b>Weapon upgrade:</b> 1 Tempered Ore + ${shopPrice(55,summoned)}g for the first upgrade.<br>Type: <b>buy [item]</b>, <b>sell [item]</b>, <b>upgrade [weapon]</b>, <b>stash</b>, <b>exit shop</b>`;}else if(type==="alchemist"){txt+="<b>Alchemist Shop</b><br>Potions, ingredients and alchemical tools only.<br>";for(const [item,base] of Object.entries(ALCHEMIST_BUY))txt+=`Buy ${item} — ${shopPrice(base,summoned)}g<br>`;txt+="<b>Recipes:</b><br>";for(const recipe of CRAFT_RECIPES_MASTER)if(!player.knownRecipes.includes(recipe.output))txt+=`Learn ${recipe.output} — ${shopPrice(recipe.cost,summoned)}g<br>`;txt+="Type: <b>buy [item]</b>, <b>sell [item]</b>, <b>learn [recipe]</b>, <b>stash</b>, <b>exit shop</b>";}else{txt+="<b>Secret Trader</b><br>";for(const [item,base] of Object.entries(SECRET_TRADER_BUY))txt+=`Buy ${item} — ${base}g<br>`;txt+="Type: <b>buy [item]</b>, <b>exit shop</b>";}displayMessage(txt,"shop");renderStatusPanel();}
function handleTraderCommand(){if(!gameState.traderRooms.includes(player.location)){displayMessage("There is no trader here.","error");return;}if(player.location===gameState.possessedTraderRoom&&!player.possessedNpcDone){displayMessage("The trader cannot speak with his own voice yet.","error");return;}if(player.possessedNpcDone&&player.location!==gameState.possessedTraderRoom&&!player.traderHeardAboutRescue){player.traderHeardAboutRescue=true;displayMessage("<i>The trader studies you a moment longer than usual. 'Heard what you did for him. Didn't think you had it in you.'</i>");return;}displayMessage("<i>The trader whispers: 'If something looks useless, keep it until the castle proves otherwise.'</i>");}
function handleBuyCommand(name){if(!gameState.activeShop){displayMessage("You are not shopping right now.","error");return;}const s=gameState.activeShop,item=canonicalItemName(name);if(!item){displayMessage("That item does not exist.","error");return;}const table=s.type==="blacksmith"?BLACKSMITH_BUY:(s.type==="alchemist"?ALCHEMIST_BUY:SECRET_TRADER_BUY);if(!(item in table)){displayMessage("You cannot buy that here.","error");return;}if(item==="Whetstone"&&s.type==="blacksmith"&&gameState.blacksmithWhetstoneStock<=0){displayMessage("The Blacksmith is out of whetstones for this visit.","error");return;}const price=s.type==="secret"?table[item]:shopPrice(table[item],s.summoned);if(player.gold<price){displayMessage(`You need ${price} gold.`,`error`);return;}const c=canAddItem(item,1);if(!c.ok){displayMessage(c.reason,"error");return;}player.gold-=price;addItem(item,1,{silent:true});if(item==="Whetstone"&&s.type==="blacksmith")gameState.blacksmithWhetstoneStock--;displayMessage(`You buy ${item} for ${price} gold.`);renderStatusPanel();}
function handleSellCommand(name){if(!gameState.activeShop){displayMessage("You are not shopping right now.","error");return;}const s=gameState.activeShop;if(s.type==="secret"){displayMessage("The secret trader is not buying.","error");return;}const it=getInventoryItem(name);if(!it){displayMessage("You do not have that item.","error");return;}const table=s.type==="blacksmith"?BLACKSMITH_SELL:ALCHEMIST_SELL;if(!(it.name in table)){displayMessage("This shop does not buy that kind of item.","error");return;}const price=table[it.name];removeItem(it.name,1);player.gold+=price;displayMessage(`You sell ${it.name} for ${price} gold.`);renderStatusPanel();}
function handleLearnCommand(name){if(!gameState.activeShop||gameState.activeShop.type!=="alchemist"){displayMessage("Recipes can only be learned from the Alchemist.","error");return;}const r=CRAFT_RECIPES_MASTER.find(x=>normalizeText(x.output)===normalizeText(name));if(!r){displayMessage("Unknown recipe.","error");return;}if(player.knownRecipes.includes(r.output)){displayMessage("You already know that recipe.");return;}const price=shopPrice(r.cost,gameState.activeShop.summoned);if(player.gold<price){displayMessage(`You need ${price} gold.`,`error`);return;}player.gold-=price;player.knownRecipes.push(r.output);displayMessage(`You learn the recipe for ${r.output}.`);renderStatusPanel();}
function handleCraftCommand(name){const r=CRAFT_RECIPES_MASTER.find(x=>normalizeText(x.output)===normalizeText(name));if(!r){displayMessage("Unknown recipe.","error");return;}if(!player.knownRecipes.includes(r.output)){displayMessage("You do not know that recipe.","error");return;}for(const ing of r.items)if(!getInventoryItem(ing)){displayMessage(`You lack: ${ing}.`,`error`);return;}const c=canAddItem(r.output,1);if(!c.ok){displayMessage(c.reason,"error");return;}r.items.forEach(ing=>removeItem(ing,1));addItem(r.output,1,{silent:true});displayMessage(`You craft ${r.output}.`);renderStatusPanel();}
function handleUpgradeCommand(name){if(!gameState.activeShop||gameState.activeShop.type!=="blacksmith"){displayMessage("Weapons can only be upgraded by the Blacksmith.","error");return;}const it=getInventoryItem(name);if(!it){displayMessage("You do not have that weapon.","error");return;}const d=ITEM_DEFS[it.name];if(!d||!["weapon","legendary"].includes(d.type)){displayMessage("That item cannot be reforged as a weapon.","error");return;}if(!getInventoryItem("Tempered Ore")){displayMessage("The Blacksmith needs 1 Tempered Ore.","error");return;}const up=it.upgrade||0;if(up>=3){displayMessage("This weapon cannot be improved any further.","error");return;}const price=shopPrice(55+up*20,gameState.activeShop.summoned);if(player.gold<price){displayMessage(`The upgrade costs ${price} gold.`,`error`);return;}player.gold-=price;removeItem("Tempered Ore",1);it.upgrade=up+1;displayMessage(`<i>The Blacksmith works the Tempered Ore into the metal until the weapon glows white.</i><br><b>${it.name} is now +${it.upgrade}.</b> (+2 attack per upgrade)`,`header`);renderStatusPanel();}

function attemptTowerClimb(){if(player.location!==48)return false;if(!getInventoryItem("Rope")){displayMessage("The final stairway has collapsed. You need a Rope to reach the Tower Apex.","error");return true;}const res=resolveRopeUse("tower");if(!res.used)return true;gameState.towerRopeIntact=!res.broke;moveToRoom(49);enterFinalRoom();return true;}
function handleTowerDescent(){if(player.location!==49)return false;if(gameState.towerSecretEscape){displayMessage("You use the hidden route and descend safely.");moveToRoom(48);return true;}if(gameState.towerRopeIntact){displayMessage("You climb back down the Rope.");moveToRoom(48);return true;}displayMessage("The Rope is gone. You cannot climb down. Try <b>jump down</b>, or use something that might reveal another route.","error");return true;}
function handleJumpDown(){if(player.location!==49){displayMessage("Jumping down here would only make you look foolish.","error");return;}const loss=Math.max(1,Math.ceil(player.maxHP*.35));player.hp=Math.max(1,player.hp-loss);adjustDread(8);displayMessage(`You jump from the broken tower ledge and crash onto the lower landing. You lose ${loss} HP.`,`error`);moveToRoom(48);}
function enterFinalRoom(){const keys=LEGENDARY_KEYS.filter(k=>getInventoryItem(k.name));if(!keys.length){displayMessage("The great door does not move. Four key-shaped wounds glow faintly across its surface.<br>You have reached the top, but you are not ready to open it.","header");return;}if(keys.length===1){displayMessage(`Only one legendary key answers the door: <b>${keys[0].name}</b>. The castle accepts your choice.`);handleChooseEnding(keys[0].name);return;}let txt="The keys vibrate in your pack.<br><b>Every key has a soul. Choose at your own risk. Only one may open the way.</b><br>"+keys.map((k,i)=>`${i+1}. ${k.name} — ${k.desc}`).join("<br>")+"<br>Type: <b>choose [key name]</b>";displayMessage(txt,"header");runtime.awaitingEndingChoice=true;}
function consumeLegendaryKey(name){removeItem(name,1);}
function handleChooseEnding(name){const key=LEGENDARY_KEYS.find(k=>normalizeText(k.name)===normalizeText(name));if(!key||!getInventoryItem(key.name)){displayMessage("You do not have that key.","error");return;}runtime.awaitingEndingChoice=false;consumeLegendaryKey(key.name);if(key.name==="Meteorite Key"){runtime.endingType="meteorite";displayMessage("<b>The Meteorite Key burns through the lock.</b><br>A roar shakes the tower. Xykon unfolds from the darkness, scales glowing like a dying star.","header");startCombat(scaleEnemy({name:"Xykon the Dragon",hp:38,attack:10,defense:6,xp:55,miss:.12}));return;}if(key.name==="Ice Key"){runtime.endingType="ice";runtime.awaitingIceChoice=true;displayMessage("<b>Frost seals the room.</b><br>Lysandra stands beyond the door, alive—and smiling.<br>'Free me and leave, or stay and rule this place with me.'<br>Type <b>free</b> or <b>join</b>.","header");return;}if(key.name==="Shadow Key"){runtime.endingType="shadow";displayMessage("<b>The door opens onto darkness without walls.</b><br>A voice asks whether you are clever enough to leave.","header");startRiddleChallenge("shadowEnding",5);return;}if(key.name==="Sunfire Key"){runtime.endingType="sunfire";displayMessage("<b>The Sunfire Key becomes light.</b><br>The curse peels away from the castle stone by stone. The dead fall silent, the smoke clears, and the first clean sunrise reaches the tower.<br><b>True Ending</b>","header");endGame();}}
function endGame(){gameState.gameEnded=true;inCombat=false;currentEnemy=null;runtime.awaitingEndingChoice=false;runtime.awaitingIceChoice=false;recordEndingSeen(runtime.endingType);displayMessage("<b>THE END</b><br>Thank you for playing Castle of Dread.<br>Use <b>reset</b> to begin another run.","header");}

function handleHelp(){const scrolls=getInventoryItem("Save Scroll")?.qty||0,savesLeft=(player.hasBaseSave?1:0)+scrolls;let h="<b>Available commands:</b><br><b>go [direction]</b> — north, south, east, west<br><b>take [item]</b> — pick up loose loot<br><b>open [item]</b> — open a chest or object<br><b>inventory</b> / <b>inv</b><br><b>equip [weapon]</b><br><b>use [item]</b><br><b>map</b>, <b>status</b><br><b>save</b>, <b>load</b>, <b>reset</b><br><b>manual</b> — full explanation of game systems<br><b>bestiary</b> — creatures encountered &amp; endings found, across all runs<br>";h+=`<span style="color:#ffe68a;">Saves available: ${savesLeft}</span><br>`;if(player.location===gameState.blacksmithRoom)h+="<b>blacksmith</b> — speak to the Blacksmith<br>";if(player.location===gameState.alchemistRoom)h+="<b>alchemist</b> — speak to the Alchemist<br>";if(gameState.traderRooms.includes(player.location))h+="<b>trader</b> — speak to the Trader<br>";if(gameState.activeShop){h+="<b>buy [item]</b>, <b>sell [item]</b>, <b>stash</b>, <b>exit shop</b><br>";if(gameState.activeShop.type==="blacksmith")h+="<b>upgrade [weapon]</b><br>";if(gameState.activeShop.type==="alchemist")h+="<b>learn [recipe]</b><br>";}if(player.knownRecipes.length)h+="<b>recipes</b>, <b>craft [item]</b><br>";if(player.statPoints>0)h+="<b>levelup [stat]</b> — hp, attack, defense, mana, weight, luck, flee<br>";if(canAccessStash())h+="<b>stash</b>, <b>store [item]</b>, <b>retrieve [item]</b><br>";if(player.location===49&&!gameState.towerRopeIntact&&!gameState.towerSecretEscape)h+="<b>jump down</b> — dangerous tower escape<br>";displayMessage(h,"header");}
const TOTAL_ENDING_TYPES=6; // coward, ice_help, ice_join, meteorite, shadow, sunfire
function handleBestiary(){const seen=meta.enemiesSeen.length,total=ENEMY_POOL.length,endings=meta.endingsSeen.length;displayMessage(`<b>Castle Records</b><br>Creatures encountered: ${seen}/${total}<br>Endings discovered: ${endings}/${TOTAL_ENDING_TYPES}<br><i>(Tracked across all playthroughs. Resetting a run does not erase this.)</i>`,"header");}
const MANUAL_HTML=`<b>CASTLE OF DREAD — MANUAL</b><br><br>
<b>Movement:</b> Use <b>go [direction]</b> (north/south/east/west). If a room is pitch dark, you can still move blindly — the game will never lie about whether an exit exists, but you won't see the room description or its contents until you have light.<br><br>
<b>Combat:</b> Turn-based. <b>attack</b>, <b>use [item]</b>, <b>equip [weapon]</b> or <b>flee</b> during a fight. Wizards spend Mana per attack; running out weakens your strikes until Mana regenerates (after combat and when entering new rooms).<br><br>
<b>Inventory &amp; Weight:</b> Every item has weight. Carrying too much slows your reflexes — worse odds to hit, worse odds to flee, more damage taken. Keep your load reasonable.<br><br>
<b>Chests:</b> Not every chest is what it seems. Some are trapped, some are stuck, some bite back. Certain tools (Lockpick, Crowbar, Oil Can, Bucket of Water) solve certain problems — carrying a variety of tools is safer than specializing in one.<br><br>
<b>Darkness &amp; Torches:</b> Some rooms have no light at all. A Torch reveals a room's details for a limited number of moves, then burns out.<br><br>
<b>Poison:</b> Some creatures can poison you. It burns for a couple of rooms as you keep moving, then fades on its own — or cure it instantly at any time with a Potion Antidote (buy from the Alchemist, or craft it from Herb + Mushroom).<br><br>
<b>Creatures:</b> Different wings of the castle favor different kinds of danger, and not every creature fights the same way — some drain your strength when they land a hit, some shriek to throw off your aim, some gather power before a heavier blow. Pay attention to what an enemy does, not just its name.<br><br>
<b>An Uneasy Quiet:</b> Sometimes, before anything happens, you'll hear something — a sound, a direction. Trust that something is coming. Don't trust the direction completely; stone has a way of lying about where a sound came from.<br><br>
<b>Cleared Rooms:</b> A room you've made safe usually stays that way — for a while. Nothing in this castle stays empty forever if you're gone long enough.<br><br>
<b>Cursed Items:</b> A few rare, powerful items come with a price attached. They will not announce the price. Decide for yourself whether the power is worth it.<br><br>
<b>Riddles:</b> Certain encounters will not let you leave until you answer correctly. Wrong answers cost you — sometimes health, sometimes a shaky grip that reduces how much you can carry for a while. Persistence pays off.<br><br>
<b>Fleeing:</b> Running from a fight gets harder the longer you try and fail — desperation is not a strategy on its own.<br><br>
<b>Castle Mood:</b> The castle reacts to what happens to you. Reckless choices and close calls make it more dangerous; time and calm passing through it lets that tension fade. Pay attention to how it feels, not just to the numbers on your sheet.<br><br>
<b>Difficulty:</b> Changeable anytime from the Settings screen — Easy, Normal, Hard, or Extreme. Higher difficulties mean tougher, more frequent creatures and a faster-rising Castle Mood. On Extreme, some encounters hide more than one creature.<br><br>
<b>Castle Records:</b> Type <b>bestiary</b> anytime to see how many different creatures you've encountered and how many endings you've found — tracked across every playthrough, not just this one.<br><br>
<b>Shops:</b> The Blacksmith deals only in weapons and combat tools — swords, axes, bows, and arcane implements like tomes and staves alike. The Alchemist deals only in potions, ingredients and recipes. Each will hand you a summoning scroll the first time you meet them — using it calls them to you, but summoned prices run higher.<br><br>
<b>Weapon Upgrades:</b> The Blacksmith can reforge a weapon if you bring gold and a rare crafting material found only by exploring and fighting. A Whetstone offers a smaller, cheaper edge (up to +2 attack) on ordinary weapons — the Blacksmith only carries a couple per visit, and legendary weapons are beyond what a whetstone can do.<br><br>
<b>Leveling Up:</b> Gaining a level grants you one point to spend as you choose — HP, Attack, Defense, Mana, Carry Weight, Luck or Flee chance. Build your character your way.<br><br>
<b>Saving:</b> You begin each run with exactly one free save. Beyond that, you must find rare Save Scrolls hidden in the castle — each one grants exactly one more save. All saves overwrite the same run; there is no going back to an earlier point once you've saved over it. Choose your save moments carefully.<br><br>
<b>The Tower:</b> The final stretch of the castle is not simply a walk upward. Come prepared, and pay attention to your equipment and its condition.<br><br>
<b>Endings:</b> The castle remembers what you carry when you reach the top. Different playthroughs can end very differently — the game will not tell you how in advance.<br><br>
Type <b>help</b> at any time for a quick command reference.`;
function handleManual(){displayMessage(MANUAL_HTML,"header");}
function handleMovement(dir){const r=gameState.dungeon[player.location];if(!r)return;if(player.location===0&&dir==="south"){displayMessage("You stare at the castle, reconsider every decision that brought you here, and turn around.<br>The bridge collapses under your first confident step.<br><b>COWARD'S ENDING — GAME OVER.</b>","error");gameState.gameEnded=true;recordEndingSeen("coward");return;}if(runtime.activeRiddle){displayMessage("Something in this room will not let you leave until the riddles are answered.","error");return;}if(player.location===49&&dir==="south"){handleTowerDescent();return;}const dest=r.exits[dir];if(typeof dest!=="number"){displayMessage(r.type==="dark"&&player.torchRoomsLeft<=0?"You feel along the wall in the darkness, but there is no passage that way.":"You cannot go that way.","error");return;}if(dest===49&&player.location===48){attemptTowerClimb();return;}if(dest<0){displayMessage("You cannot go that way.","error");return;}if(gameState.dungeon[dest]&&gameState.dungeon[dest].type==="dark"&&player.torchRoomsLeft>0)displayMessage("<i>The torchlight flickers as you approach.</i>");gameState.activeShop=null;exitInventoryPanel();if(!moveToRoom(dest))return;if(dest!==49&&!runtime.activeRiddle){let e=null;if(gameState.pendingThreat&&gameState.pendingThreat.realTarget===dest){const pt=gameState.pendingThreat;gameState.pendingThreat=null;if((gameState.totalMoves||0)<=pt.expiresAtMove){const pool=getZonePool(dest),base=pool[Math.floor(Math.random()*pool.length)];e=scaleEnemy(base);gameState.dungeon[dest].enemy=e;}else displayMessage("Whatever made that sound is gone now.","error");}if(!e)e=spawnEnemy(dest);if(e)startCombat(e);else maybeGenerateThreatHint(dest);}}
function handleCommand(raw){const cmd=normalizeText(raw);if(!cmd)return;if(gameState.gameEnded){if(cmd==="load"){loadGame();return;}if(cmd==="reset"){resetGameConfirmation();return;}if(cmd==="manual"){handleManual();return;}if(cmd==="bestiary"||cmd==="codex"){handleBestiary();return;}displayMessage("This run has ended. Use load or reset.","error");return;}if(inCombat&&currentEnemy){processCombatCommand(cmd);return;}if(runtime.awaitingIceChoice){if(cmd==="join"){runtime.awaitingIceChoice=false;runtime.endingType="ice_join";displayMessage("<b>You take Lysandra's hand.</b><br>The castle gains two rulers and the world outside slowly forgets your name.<br><b>Dark Crown Ending</b>","header");endGame();return;}if(cmd==="free"){runtime.awaitingIceChoice=false;runtime.endingType="ice_help";displayMessage("<b>You break Lysandra's chains and refuse the throne.</b><br>Together you descend before the castle can close around you.<br><b>Mercy Ending</b>","header");endGame();return;}if(cmd==="help"){displayMessage("The choice will not wait for a command list. Type <b>free</b> or <b>join</b>.","error");return;}displayMessage("Choose: free or join.","error");return;}if(runtime.awaitingEndingChoice){if(cmd.startsWith("choose ")){handleChooseEnding(cmd.slice(7));return;}if(cmd==="inventory"||cmd==="inv"){renderInventoryPanel();return;}if(cmd==="status"){renderStatusPanel();return;}if(cmd==="save"){saveGame();return;}if(cmd==="manual"){handleManual();return;}displayMessage("The door is waiting for a key choice.","error");return;}if(runtime.activeRiddle){if(cmd.startsWith("answer ")){handleAnswerCommand(cmd.slice(7));return;}if(cmd==="inventory"||cmd==="inv"){renderInventoryPanel();return;}if(cmd==="status"){renderStatusPanel();return;}if(cmd==="save"){saveGame();return;}if(cmd==="manual"){handleManual();return;}displayMessage("The riddle holds you here. Type: answer [your answer].","error");return;}if(cmd==="help"||cmd==="commands"){handleHelp();return;}if(cmd==="manual"){handleManual();return;}if(cmd==="bestiary"||cmd==="codex"){handleBestiary();return;}if(cmd==="save"){saveGame();return;}if(cmd==="load"){loadGame();return;}if(cmd==="reset"){resetGameConfirmation();return;}if(cmd==="inventory"||cmd==="inv"){renderInventoryPanel();return;}if(cmd==="exit"){exitInventoryPanel();return;}if(cmd==="map"){renderMap();displayMessage("Map updated.");return;}if(cmd==="status"){renderStatusPanel();displayMessage("Status updated.");return;}if(cmd.startsWith("go ")){handleMovement(cmd.slice(3));return;}if(cmd==="jump down"){handleJumpDown();return;}if(cmd.startsWith("take ")){handleTakeCommand(cmd.slice(5));return;}if(cmd.startsWith("open ")){handleOpenItemCommand(cmd.slice(5));return;}if(cmd.startsWith("equip ")){handleEquipCommand(cmd.slice(6));return;}if(cmd.startsWith("use ")){handleUseCommand(cmd.slice(4));return;}if(cmd==="blacksmith"){openShop("blacksmith",false);return;}if(cmd==="alchemist"){openShop("alchemist",false);return;}if(cmd==="trader"){handleTraderCommand();return;}if(cmd==="shop"){if(player.location===gameState.blacksmithRoom)openShop("blacksmith",false);else if(player.location===gameState.alchemistRoom)openShop("alchemist",false);else displayMessage("There is no shop here.","error");return;}if(cmd.startsWith("buy ")){handleBuyCommand(cmd.slice(4));return;}if(cmd.startsWith("sell ")){handleSellCommand(cmd.slice(5));return;}if(cmd.startsWith("upgrade ")){handleUpgradeCommand(cmd.slice(8));return;}if(cmd.startsWith("learn ")){handleLearnCommand(cmd.slice(6));return;}if(cmd.startsWith("craft ")){handleCraftCommand(cmd.slice(6));return;}if(cmd==="recipes"){displayMessage(player.knownRecipes.length?"<b>Known recipes:</b><br>"+player.knownRecipes.join("<br>"):"You do not know any recipes yet.",player.knownRecipes.length?undefined:"error");return;}if(cmd==="stash"){renderStashPanel();return;}if(cmd.startsWith("store ")){handleStoreCommand(cmd.slice(6));return;}if(cmd.startsWith("retrieve ")){handleRetrieveCommand(cmd.slice(9));return;}if(cmd==="exit shop"){gameState.activeShop=null;exitInventoryPanel();displayMessage("You step away from the shop.");return;}if(cmd.startsWith("levelup ")){handleLevelUpChoice(cmd.slice(8));return;}displayMessage("Unknown command. Type help.","error");}

function saveGame(){let usedScroll=false;if(player.hasBaseSave){if(typeof confirm==="function"&&!confirm("This will use your only free save for this run. After this, you'll need a Save Scroll to save again. Continue?"))return;player.hasBaseSave=false;}else if(getInventoryItem("Save Scroll")){removeItem("Save Scroll",1);usedScroll=true;}else{displayMessage("You have no way to save right now. Your free save is already used. Find a Save Scroll somewhere in the castle.","error");return;}try{localStorage.setItem(SAVE_KEY,JSON.stringify({player,gameState,currentEnemy,inCombat,runtime}));const scrollsLeft=getInventoryItem("Save Scroll")?.qty||0;displayMessage(`Game saved successfully!${usedScroll?" (Save Scroll consumed.)":""}${!player.hasBaseSave&&!scrollsLeft?" You have no more ways to save unless you find another Save Scroll.":""}`,"header");}catch(err){console.error(err);displayMessage("Failed to save game.","error");if(usedScroll)addItem("Save Scroll",1,{silent:true});else player.hasBaseSave=true;}}
function loadGame(){try{const raw=localStorage.getItem(SAVE_KEY);if(!raw){displayMessage("No saved game found.","error");return;}const d=JSON.parse(raw);player=d.player;if(typeof player.poison==="boolean"&&player.poisonTurns===undefined){player.poisonTurns=player.poison?3:0;delete player.poison;}gameState=d.gameState;gameState.roomCoords=computeRoomCoords();currentEnemy=d.currentEnemy||null;inCombat=!!d.inCombat;runtime=d.runtime||{activeRiddle:null,awaitingEndingChoice:false,awaitingIceChoice:false,endingType:null};document.getElementById("main-menu-screen")?.classList.add("hidden");document.getElementById("char-creation-screen")?.classList.add("hidden");document.getElementById("story-screen")?.classList.add("hidden");document.getElementById("settings-screen")?.classList.add("hidden");document.getElementById("game-screen")?.classList.remove("hidden");renderMap();renderStatusPanel();displayRoom(player.location);if(inCombat&&currentEnemy)displayMessage(`<b>Combat restored:</b> ${currentEnemy.name} — HP ${currentEnemy.hp}`,"header");if(runtime.activeRiddle)displayMessage(`<b>Riddle restored:</b><br>${runtime.activeRiddle.current.q}<br>Type: <b>answer [your answer]</b>`,`riddle`);displayMessage("Game loaded successfully!","header");}catch(err){console.error(err);displayMessage("Failed to load game.","error");}}
function resetGameConfirmation(){if(confirm("Are you sure you want to reset ALL progress?")){localStorage.removeItem(SAVE_KEY);window.location.reload();}else displayMessage("Reset cancelled.");}

function resetPlayerForNewRun(){const n=player.name,g=player.gender,c=player.class,cn=player.className,d=CLASS_DEFS[c];player={name:n,gender:g,class:c,className:cn,hp:d.maxHP,maxHP:d.maxHP,mana:d.mana,maxMana:d.mana,attack:d.attack,defense:d.defense,xp:0,level:1,gold:30,maxWeight:d.maxWeight,inventory:[],chest:[],equipped:{weapon:null},discovered:{},location:0,previousLocation:0,luck:0,fleeChance:d.fleeChance,missChance:d.missChance,poisonTurns:0,statusEffects:[],knownRecipes:[],statPoints:0,torchRoomsLeft:0,blacksmithGreeted:false,alchemistGreeted:false,riddleSpiritDone:false,possessedNpcDone:false,hallOfMirrorsSecret:false,runeSecret:false,silverSecret:false,mapSecret:false,secretTraderUsed:false,wellSecret:false,seenTemperedOreLore:false,hasBaseSave:true,rattledTurns:0,rattledAmount:0,lastStandUsed:false,lastStandTurns:0,traderHeardAboutRescue:false};currentEnemy=null;inCombat=false;runtime={activeRiddle:null,awaitingEndingChoice:false,awaitingIceChoice:false,endingType:null};}
function startGame(){resetPlayerForNewRun();initDungeon();if(player.class==="warrior"){addItem("Rusty Sword",1,{silent:true});addItem("Potion HP",1,{silent:true});player.equipped.weapon="Rusty Sword";}else if(player.class==="mage"){addItem("Tome of Fire",1,{silent:true});addItem("Potion HP",1,{silent:true});addItem("Potion Mana",1,{silent:true});player.equipped.weapon="Tome of Fire";}else{addItem("Old Dagger",1,{silent:true});addItem("Potion HP",1,{silent:true});addItem("Lockpick",1,{silent:true});player.equipped.weapon="Old Dagger";}document.getElementById("main-menu-screen")?.classList.add("hidden");document.getElementById("char-creation-screen")?.classList.add("hidden");document.getElementById("game-screen")?.classList.remove("hidden");const out=document.getElementById("game-text-output");if(out)out.innerHTML="";renderMap();renderStatusPanel();displayRoom(0);displayMessage("Type <b>help</b> to see your current commands.");}
window.onload=function(){const sm=document.getElementById("start-game-button-menu"),sc=document.getElementById("start-game-button-char-create"),sb=document.getElementById("story-button"),setb=document.getElementById("settings-button"),bs=document.getElementById("back-to-menu-button-story"),bst=document.getElementById("back-to-menu-button-settings"),submit=document.getElementById("submit-command"),input=document.getElementById("command-input"),mb=document.getElementById("manual-button-menu"),bmn=document.getElementById("back-to-menu-button-manual");if(mb)mb.onclick=()=>{const c=document.getElementById("manual-screen-content");if(c)c.innerHTML=MANUAL_HTML;document.getElementById("main-menu-screen")?.classList.add("hidden");document.getElementById("manual-screen")?.classList.remove("hidden");};if(bmn)bmn.onclick=()=>{document.getElementById("manual-screen")?.classList.add("hidden");document.getElementById("main-menu-screen")?.classList.remove("hidden");};if(sm)sm.onclick=()=>{document.getElementById("main-menu-screen")?.classList.add("hidden");document.getElementById("char-creation-screen")?.classList.remove("hidden");};if(sc)sc.onclick=()=>{const name=document.getElementById("player-name")?.value.trim(),gender=Array.from(document.getElementsByName("gender")).find(i=>i.checked),cl=Array.from(document.getElementsByName("class")).find(i=>i.checked);if(!name||!gender||!cl){alert("Fill out all fields!");return;}player.name=name;player.gender=gender.value;player.class=cl.value;player.className=CLASS_DEFS[cl.value].name;startGame();};if(sb)sb.onclick=()=>{document.getElementById("main-menu-screen")?.classList.add("hidden");document.getElementById("story-screen")?.classList.remove("hidden");};if(setb)setb.onclick=()=>{document.getElementById("main-menu-screen")?.classList.add("hidden");document.getElementById("settings-screen")?.classList.remove("hidden");};if(bs)bs.onclick=()=>{document.getElementById("story-screen")?.classList.add("hidden");document.getElementById("main-menu-screen")?.classList.remove("hidden");};if(bst)bst.onclick=()=>{document.getElementById("settings-screen")?.classList.add("hidden");document.getElementById("main-menu-screen")?.classList.remove("hidden");};const diffButtons=document.querySelectorAll(".difficulty-btn");function refreshDifficultyUI(){diffButtons.forEach(b=>b.classList.toggle("selected",b.getAttribute("data-difficulty")===getDifficulty()));const desc=document.getElementById("difficulty-desc");if(desc)desc.textContent=currentDifficultyDef().desc;}diffButtons.forEach(b=>{b.onclick=()=>{setDifficulty(b.getAttribute("data-difficulty"));refreshDifficultyUI();};});refreshDifficultyUI();const send=()=>{if(!input)return;const v=input.value.trim();if(!v)return;handleCommand(v);input.value="";input.focus();};if(submit)submit.onclick=send;if(input)input.addEventListener("keydown",e=>{if(e.key==="Enter")send();});};

